const mainNav=[['Dashboard','home','home'],['Explore stocks','explore','search'],['Execution','plan/selections','plan'],['Portfolio','portfolio','portfolio'],['Orders','orders','orders'],['Risk & alerts','risk','shield'],['Analysis','analysis','pulse']];
const toolsNav=[['Sectors','sectors','globe'],['Tools','tools','flask'],['Watchlist','watchlist','star'],['News & events','news','news'],['Performance','performance','chart'],['Reports','reports','report'],['Broker & capital','broker','broker'],['Model results','results','flask'],['Activity history','activity','history']];
const utilityNav=[['Settings','settings/profile','settings']];
function navItem([name,route,ico]){const base=currentRoute.split('/')[0],active=base===route.split('/')[0]||base==='company'&&route==='explore'||base==='holding'&&route==='portfolio'||base==='order'&&route==='orders'||['learn','article','support','sitemap'].includes(base)&&route==='settings/profile';return `<a class="nav-item ${active?'active':''}" href="#/${route}" ${active?'aria-current="page"':''}>${icon(ico)}${name}${route==='risk'?'<span class="count">'+riskIssues().filter(x=>x.level!=="info").length+'</span>':''}</a>`;}
function accountControls(){return `<div class="account-controls">${themeControl()}<a href="#/notifications" class="btn icon-only" aria-label="Notifications" title="Notifications">${icon('bell')}<span class="notification-dot"></span></a><a href="#/settings/profile" class="profile-control" aria-label="Profile and settings"><span class="avatar">${esc(state.displayName.split(' ').map(p=>p[0]).slice(0,2).join('').toUpperCase())}</span><span class="profile-name">${esc(state.displayName)}</span></a></div>`;}
function strategyBar(){const expanded=sidebarExpanded();return `<header class="workspace-header"><button class="btn icon-only sidebar-toggle ${expanded?'expanded':''}" data-action="sidebar-toggle" aria-label="${expanded?'Hide sidebar':'Show sidebar'}" title="${expanded?'Hide sidebar':'Show sidebar'}" aria-controls="workspace-sidebar" aria-expanded="${expanded}">${icon(isMobileViewport()?'menu':'chevron')}</button><nav class="strategy-tabs" aria-label="Strategy workspace">${Object.entries(strategyList).map(([key,s])=>`<a href="#/${currentRoute}" data-strategy="${key}" class="strategy-tab ${state.strategy===key?'active':''}" ${state.strategy===key?'aria-current="true"':''}>${icon(s.icon)}${s.name}</a>`).join('')}</nav><form class="search-shell header-search" id="global-search" role="search">${icon('search')}<input name="q" aria-label="Search companies, symbols, industries, and tools" placeholder="Search stocks & tools…"><kbd>/</kbd></form><div class="header-broker-controls"><div class="exchange-toggle" role="group" aria-label="Exchange"><button type="button" class="exch-btn ${(state.exchange||'NSE')==='NSE'?'active':''}" data-action="set-exchange" data-exchange="NSE" aria-pressed="${(state.exchange||'NSE')==='NSE'}">NSE</button><button type="button" class="exch-btn ${state.exchange==='BSE'?'active':''}" data-action="set-exchange" data-exchange="BSE" aria-pressed="${state.exchange==='BSE'}">BSE</button></div><a href="#/broker" class="broker-pill"><span class="broker-dot" style="background:${broker().color}"></span>${broker().name}<span class="muted">•• 1042</span>${tradeMode()==='paper'?'<span class="paper-chip">Paper</span>':''}</a>${killSwitchButton()}</div>${accountControls()}</header>`;}
function shell(content){const expanded=sidebarExpanded();return `${state.mobileSidebarOpen?'<button type="button" class="sidebar-backdrop" data-action="sidebar-toggle" aria-label="Close navigation"></button>':''}<aside id="workspace-sidebar" class="sidebar ${state.mobileSidebarOpen?'open':''}" aria-label="Main navigation" ${!expanded?'inert aria-hidden="true"':''}><div class="sidebar-brand-row">${logo()}${action(icon('close'),'sidebar-toggle','btn icon-only sidebar-close','aria-label="Close sidebar"')}</div><nav class="nav-scroll" aria-label="Workspace">${orderedNavigation('main').map(navItem).join('')}</nav><div class="sidebar-bottom"><button type="button" class="nav-item more-tools-toggle" data-action="toggle-tools" aria-expanded="${state.toolsOpen}" aria-controls="sidebar-tool-panel">${icon('grid')}<span>More tools</span><span class="tools-chevron" aria-hidden="true">${state.toolsOpen?'‹':'›'}</span></button><div class="sidebar-utilities">${utilityNav.map(navItem).join('')}<button type="button" class="nav-item signout-button" data-action="signout">${icon('external')}Sign out</button></div></div></aside>${toolsFlyout()}<div class="workspace">${isAdmin()?'<div class="admin-return-bar">Administrator viewing client workspace · <a href="#/admin">Return to Admin</a></div>':''}${killBanner()}${strategyBar()}<main class="page" id="main">${content}${footer()}</main></div>${currentRoute.split('/')[0]==='settings'||!prefs().showChat?'':chatWidget()}<nav class="mobile-bottom" aria-label="Mobile navigation">${[...mainNav.slice(0,4),['More','settings/workspace','grid']].map(([n,r,i])=>`<a href="#/${r}" class="${currentRoute.split('/')[0]===r.split('/')[0]?'active':''}">${icon(i)}${n}</a>`).join('')}</nav>`;}
function publicShell(content){return `<div class="public-shell"><header class="public-header">${logo('welcome')}<nav class="public-nav" aria-label="Company navigation">${link('Our platform','features','')}${link('How it works','how-it-works','')}${link('Pricing','pricing','')}${link('About us','about','')}${link('Contact','contact','')}</nav><div class="public-header-actions">${themeControl()}${link('Register','register','btn primary')}${link('Login','login','btn')}</div></header><main id="main" class="public-main">${content}</main><footer class="public-footer"><div>${logo('welcome')}<p style="margin-top:12px">Research with purpose. Invest with clarity.</p><p class="small">© 2026 INVESTSIGHT CAPITAL</p></div><div class="row wrap">${link('About us','about','')}${link('Contact','contact','')}${link('Help','public-help','')}${link('Risk information','legal/risk','')}${link('Privacy','legal/privacy','')}${link('Terms','legal/terms','')}</div></footer></div>`;}
function historySeries(key=state.strategy,range=state.range[key]){const a=account(key);const count=range==='1D'?24:range==='1M'?22:40;const start=range==='1D'?a.equity-a.daily:range==='1M'?a.equity-a.net*.35:range==='3M'?a.equity-a.net*.7:a.capital;const values=Array.from({length:count},(_,i)=>{const t=i/(count-1);return Number((start+(a.equity-start)*t+Math.sin(i*1.7)*a.equity*.002*Math.sin(Math.PI*t)).toFixed(2));});values[0]=Number(start.toFixed(2));values[count-1]=Number(a.equity.toFixed(2));return values;}
function chart(type='equity',id='chart',c=stockData[0],style=''){const asLine=style==='line'||state.chartStyle!=='candle';
 const range=state.range[state.strategy];const values=type==='equity'?historySeries():Array.from({length:32},(_,i)=>c.price*(.97+i/31*.03+Math.sin(i*1.25)*.004*Math.sin(Math.PI*i/31)));if(type!=='equity')values[values.length-1]=c.price;
 const min=Math.min(...values)*.997,max=Math.max(...values)*1.003,x=i=>58+i*760/(values.length-1),y=v=>342-(v-min)/(max-min)*286;
 const points=values.map((v,i)=>`${x(i).toFixed(1)},${y(v).toFixed(1)}`),d=points.map((p,i)=>(i?'L':'M')+p).join(' ');
 const labels=range==='1D'?['09:15','10:30','11:45','13:00','14:15','15:30']:range==='1M'?['23 Sep','29 Sep','05 Oct','11 Oct','17 Oct','23 Oct']:range==='3M'?['23 Jul','10 Aug','28 Aug','16 Sep','04 Oct','23 Oct']:['23 Apr','28 May','03 Jul','07 Aug','12 Sep','23 Oct'];
 const candles=values.map((v,i)=>{const prev=values[Math.max(0,i-1)],open=prev+(v-prev)*.35,close=v,wiggle=(max-min)*(.07+(i%4)*.012),high=Math.min(max,v+wiggle),low=Math.max(min,Math.min(open,v)-wiggle*.82),up=close>=open,xx=x(i),bodyTop=y(Math.max(open,close)),bodyHeight=Math.max(3,Math.abs(y(open)-y(close)));return `<path d="M${xx.toFixed(1)} ${y(high).toFixed(1)}V${y(low).toFixed(1)}" stroke="${up?'var(--positive)':'var(--negative)'}" stroke-width="1.5"/><rect x="${(xx-5).toFixed(1)}" y="${bodyTop.toFixed(1)}" width="10" height="${bodyHeight.toFixed(1)}" rx="1" fill="${up?'var(--positive)':'var(--negative)'}"/>`;}).join('');
 return `<svg class="chart chart-large" viewBox="0 0 900 400" role="img" aria-label="${type==='equity'?'Account equity':'Share price'} ${asLine?'line':'candlestick'} chart; ${range}; ending ${type==='equity'?money(values.at(-1)):fixed(c.price)}"><defs><linearGradient id="${id}-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="var(--brand)" stop-opacity=".18"/><stop offset="1" stop-color="var(--brand)" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3,4].map(i=>{const yy=56+i*71;const value=max-(max-min)*i/4;return `<path class="chart-grid" d="M58 ${yy}H818"/><text x="836" y="${yy+4}">${type==='equity'?(value/100000).toFixed(2)+'L':Math.round(value).toLocaleString('en-IN')}</text>`}).join('')}${!asLine?candles:`<path d="${d} L818,342 L58,342Z" fill="url(#${id}-fill)"/><path d="${d}" class="chart-line"/>`}${type==='price'&&state.indicator==='ema'?`<path d="${values.map((v,i)=>(i?'L':'M')+x(i).toFixed(1)+','+(y(v)+10).toFixed(1)).join(' ')}" fill="none" stroke="#c59448" stroke-width="1.6"/>`:''}${labels.map((l,i)=>`<text x="${58+i*152}" y="379" text-anchor="${i?'middle':'start'}">${l}</text>`).join('')}</svg>${type==='price'&&state.indicator==='rsi'?`<div class="rsi-panel"><p class="small">RSI (14) · ${c.rsi} · Momentum strength</p><svg class="chart" viewBox="0 0 660 90" role="img" aria-label="RSI oscillator, reference levels 30 and 70"><path class="chart-grid" d="M42 20H590M42 65H590"/><path d="M42 60L100 45 150 50 210 35 270 42 330 30 390 40 450 26 510 35 590 28" fill="none" stroke="#a386ca" stroke-width="2"/><text x="606" y="24">70</text><text x="606" y="69">30</text></svg></div>`:''}`;
}
const rangeControls=()=>`<div class="chart-toolbar" aria-label="Chart period">${['1D','1M','3M','6M'].map(r=>`<button type="button" data-range="${r}" class="${state.range[state.strategy]===r?'active':''}" aria-pressed="${state.range[state.strategy]===r}">${r}</button>`).join('')}</div>`;
function rationale(c){return state.strategy==='long'?`${c.reason} Quality ${scores(c).quality}/100 and valuation ${scores(c).value}/100 are the main model inputs.`:state.strategy==='swing'?`${c.catalyst} supports the setup. Relative volume ${c.rvol.toFixed(1)}×, RSI ${c.rsi}, and price structure drive the swing assessment.`:`Relative volume ${c.rvol.toFixed(1)}× and positive session strength support participation following ${c.catalyst.toLowerCase()}. VWAP and execution checks remain mandatory.`;}
function withComparison(content){return `<div class="workspace-content">${content}</div>`;}
/* Shared SVG/HTML chart helpers. Colours come from theme tokens so all three appearances stay consistent. */
const chartPalette=['var(--brand)','#5b8def','#c59448','#a386ca','#e07a5f','#4fb3bf','#8aa05a','#d16d9e'];
const cashColor='#9aabb2';
function donutChart(segments,center,sub,label){const total=segments.reduce((a,s)=>a+Math.max(0,s.value),0)||1,r=62,C=2*Math.PI*r;let offset=0;const colour=(s,i)=>s.color||chartPalette[i%chartPalette.length];const rings=segments.map((s,i)=>{const len=Math.max(0,s.value)/total*C,el=`<circle cx="80" cy="80" r="${r}" fill="none" stroke="${colour(s,i)}" stroke-width="20" stroke-dasharray="${len.toFixed(2)} ${(C-len).toFixed(2)}" stroke-dashoffset="${(-offset).toFixed(2)}"><title>${esc(s.label)} · ${(Math.max(0,s.value)/total*100).toFixed(2)}%</title></circle>`;offset+=len;return el;}).join('');return `<div class="donut-wrap"><svg class="donut-chart" viewBox="0 0 160 160" role="img" aria-label="${esc(label)}: ${esc(segments.map(s=>s.label+' '+(Math.max(0,s.value)/total*100).toFixed(2)+'%').join(', '))}"><circle cx="80" cy="80" r="${r}" fill="none" stroke="var(--surface2)" stroke-width="20"/><g transform="rotate(-90 80 80)">${rings}</g><text x="80" y="80" text-anchor="middle" class="donut-center">${esc(center)}</text><text x="80" y="98" text-anchor="middle" class="donut-sub">${esc(sub)}</text></svg><ul class="chart-legend-list">${segments.map((s,i)=>`<li><i style="background:${colour(s,i)}"></i><span>${esc(s.label)}</span><strong>${s.display??(Math.max(0,s.value)/total*100).toFixed(2)+'%'}</strong></li>`).join('')}</ul></div>`;}
function barList(rows,{signed=false,format=v=>v,max=null}={}){const m=max||Math.max(1,...rows.map(r=>Math.abs(r.value)));return `<div class="bar-list${signed?' signed':''}">${rows.map((r,i)=>`<div class="bar-list-row"><span class="bar-list-label">${r.label}</span><span class="bar-list-track">${signed?`<i class="bar-zero"></i><b class="${r.value<0?'neg':'pos'}" style="${r.value<0?'right':'left'}:50%;width:${(Math.abs(r.value)/m*50).toFixed(2)}%"></b>`:`<b style="width:${Math.min(100,Math.abs(r.value)/m*100).toFixed(2)}%;background:${r.color||chartPalette[i%chartPalette.length]}"></b>`}</span><strong class="${signed?toneClass(r.value):''}">${format(r.value)}</strong></div>`).join('')}</div>`;}
function sparkline(values,cls=''){const min=Math.min(...values),max=Math.max(...values),span=max-min||1;const d=values.map((v,i)=>`${(i/Math.max(1,values.length-1)*100).toFixed(2)},${(26-(v-min)/span*22).toFixed(2)}`).join(' ');return `<svg class="metric-spark ${cls}" viewBox="0 0 100 28" preserveAspectRatio="none" aria-hidden="true"><polyline points="${d}" fill="none" vector-effect="non-scaling-stroke"/></svg>`;}
function sparkMetric(label,value,note,ico,values,tone=''){return `<div class="card metric spark-metric ${tone}"><div class="metric-label">${label}${icon(ico)}</div><div class="metric-value">${value}</div><div class="metric-note">${note}</div>${values?sparkline(values,tone):''}</div>`;}
function industryRows(key=state.strategy){const a=account(key),map=new Map();for(const h of holdings(key))map.set(h.stock.sector,(map.get(h.stock.sector)||0)+h.qty*h.stock.price);return [...map].map(([sector,value])=>({sector,value,weight:value/a.equity*100})).sort((x,y)=>y.value-x.value);}

/* Execution model: budget and stop-loss are the only client inputs; everything else is derived. */
const exitFixtures={long:[['LUMEN',40,1110,1316,'Target reached','18 Oct 2026'],['TERRA',50,980,1100,'Trailing stop','11 Oct 2026'],['ORCHID',80,584,562,'Stop-loss hit','03 Oct 2026']],swing:[['ASTER',30,1105,1245,'Target reached','21 Oct 2026'],['MERIDIAN',150,428,451,'Trailing stop','17 Oct 2026'],['SOLARIS',100,632,624,'Stop-loss hit','14 Oct 2026']],intraday:[['NEXUSTECH',30,2241,2286,'Target reached','23 Oct 2026 · 11:40 IST'],['HARBOR',60,862,876.5,'Session close','23 Oct 2026 · 15:15 IST'],['LUMEN',25,1338,1318,'Stop-loss hit','23 Oct 2026 · 10:25 IST']]};
function defaultStop(key){return aiPolicy(key).defaultStop;}
function targetPct(key,stop){return stop*aiPolicy(key).targetMultiple;}
function execSettings(key=state.strategy){const ex=state.autoExec?.[key]||{};return {budget:ex.budget||state.budgets[key],stop:ex.stop||defaultStop(key),lastRun:ex.lastRun||null};}
function stockActions(key=state.strategy){const cfg=execSettings(key),tp=targetPct(key,cfg.stop),paused=state.paused[key];
 const entered=holdings(key).map(h=>{const initialStop=h.cost*(1-cfg.stop/100),peak=Math.max(h.cost,h.peak||0,h.stock.price),stopPx=Math.max(initialStop,peak*(1-cfg.stop/100)),targetPx=h.cost*(1+tp/100);return {stock:h.stock,qty:h.qty,entry:h.cost,price:h.stock.price,peak,initialStop,stopPx,targetPx,value:h.qty*h.stock.price,pnl:h.qty*(h.stock.price-h.cost),retPct:(h.stock.price/h.cost-1)*100,progress:Math.max(0,Math.min(100,(h.stock.price-stopPx)/(targetPx-stopPx)*100))};});
 const held=new Set(entered.map(e=>e.stock.id)),plan=aiPlan(key,aiEntryCandidates(key).fresh,cfg.budget,cfg.stop),blocked=automationBlocked(key),killed=killActive(key)?killState():null;
 const waiting=plan.rows.filter(r=>!held.has(r.c.id)).map(r=>{const c=r.c,trigger=key==='long'?c.price*.985:key==='swing'?c.price+c.atr*.5:c.price*1.002;return {stock:c,qty:r.qty,value:r.value,trigger,triggerLabel:key==='long'?'Buy at or below':'Buy above',stopPx:trigger*(1-cfg.stop/100),targetPx:trigger*(1+tp/100),confidence:aiConfidence(c,key),status:killed&&killed.cancel?'Cancelled · kill switch':blocked||(paused?'On hold · press Execute':cfg.lastRun?'Waiting for entry trigger':'Starts when you press Execute')};});
 const exited=(exitFixtures[key]||[]).map(([id,qty,entry,exit,reason,date])=>({stock:stock(id),qty,entry,exit,reason,date,pnl:qty*(exit-entry),retPct:(exit/entry-1)*100}));
 if(killed&&killed.exit)entered.forEach(e=>{e.exitQueued=true;});
 return {entered,waiting,exited,realized:exited.reduce((a,x)=>a+x.pnl,0),open:entered.reduce((a,x)=>a+x.pnl,0),settings:cfg,targetPct:tp,paused,blocked};}
function actionCounters(acts){return `<div class="action-counters">${[['entered','Entered','Holding now',acts.entered.length,'check'],['waiting','Waiting','Entry pending',acts.waiting.length,'clock'],['exited','Exited','Closed by the AI',acts.exited.length,'external']].map(([k,label,sub,n,ico])=>`<a class="action-counter ${k}" href="#/plan/actions"><span class="action-counter-icon">${icon(ico)}</span><span><strong>${n}</strong><b>${label}</b><small>${sub}</small></span></a>`).join('')}</div>`;}

function rankTable(){const intraday=state.strategy==='intraday',swing=state.strategy==='swing';return table(['Rank','Company',intraday?'Relative volume':swing?'Momentum / RSI':'Quality / valuation','Model score',''],ranked().map((c,i)=>`<tr class="stock-row" data-id="${c.id}"><td><span class="rank-number">${String(i+1).padStart(2,'0')}</span></td><td>${company(c)}</td><td>${intraday?`${c.rvol.toFixed(1)}× <small class="muted">normal volume</small>`:swing?`${c.technical}/100 <small class="muted">· RSI ${c.rsi}</small>`:`${c.quality} <small class="muted">/</small> ${c.value}`}</td><td><div class="score-cell"><strong>${scores(c).total}</strong><span class="score-cell-track"><span style="width:${scores(c).total}%"></span></span></div></td><td><div class="row">${action('Compare','add-compare','btn small',`data-id="${c.id}"`)}${link('Details',`company/${c.id}/overview`,'text-link')}</div></td></tr>`));}
function dashboard(){const a=account(),s=strategy(),series=historySeries(),acts=stockActions(),intraday=state.strategy==='intraday',sectors=industryRows();
 const content=`<div class="stack"><div class="grid four">${sparkMetric('Total account value',money(a.equity),'Positions at market + cash','portfolio',series)}${sparkMetric('Net profit',signedMoney(a.net),`<span class="${toneClass(a.returnPct)}">${pct(a.returnPct)}</span> on allocated capital · ${money(a.charges)} charges deducted`,'chart',series,toneClass(a.net))}${metric(intraday?'Money in open positions':'Money in stocks',money(a.invested),`${holdings().length} ${intraday?'open positions':'holdings'} · ${(a.invested/a.equity*100).toFixed(1)}% of equity`,'layers')}${metric('Cash you can use',money(a.available),`${money(a.reserved)} reserved for pending orders`,'wallet')}</div>${dashboardIntroduction()}
 <div class="card performance-hero"><div class="card-header"><div><div class="eyebrow">${s.name.toUpperCase()} PERFORMANCE</div><h2 style="margin-top:8px">${intraday?'Your session, measured clearly.':'Your capital. Your progress.'}</h2><p>${s.lead}</p></div>${rangeControls()}</div><div class="return-strip"><div><span class="muted small">Realized P&L</span><strong class="${toneClass(a.realized)}">${signedMoney(a.realized)}</strong></div><div><span class="muted small">Open Profit/Loss</span><strong class="${toneClass(a.unrealized)}">${signedMoney(a.unrealized)}</strong></div><div><span class="muted small">Charges</span><strong>−${money(a.charges)}</strong></div><div><span class="muted small">Return on allocated capital</span><strong class="${toneClass(a.returnPct)}">${pct(a.returnPct)}</strong></div></div>${chart('equity','dashboard-equity',stockData[0],'line')}<div class="row between wrap"><span class="small muted">Account equity · includes cash · deposits excluded from profit</span>${link('View performance breakdown','performance','text-link','arrow')}</div></div>
 <div class="grid equal">${section('Automation at a glance',`${s.name} · ${automationBlocked()?automationBlocked().toLowerCase():state.paused[state.strategy]?'paused':'the AI enters and exits for you'}`,actionCounters(acts)+lines([['Budget',money(acts.settings.budget)],['Stop-loss',acts.settings.stop+'% trailing'],['Realized from AI exits',`<span class="${toneClass(acts.realized)}">${signedMoney(acts.realized)}</span>`],['Market filter',marketRegime().label],['Status',entryStatus()]])+`<h3 class="ai-log-title">Latest AI decisions</h3>${aiDecisionLog(state.strategy,3)}<div class="row wrap" style="margin-top:18px">${link('Open stock actions','plan/actions','btn primary','arrow')}${link('Change budget or stop-loss','plan/selections','btn')}</div>`)}${section('Needs your attention','Clear issues with a direct route to research',`<div class="attention-item"><span class="attention-icon">${icon('shield')}</span><div><h3>${intraday?'Review the session closeout':'Review valuation sensitivity'}</h3><p>${intraday?'Check open quantities and closeout status before the next session.':'Evergreen Consumer trades at a premium valuation. Review the thesis and downside risks.'}</p>${link('Review company',`company/${intraday?'MERIDIAN':'EVERGREEN'}/risks`,'text-link','arrow')}</div></div><div class="attention-item"><span class="attention-icon">${icon('orders')}</span><div><h3>Order partially filled</h3><p>40 shares filled. ${state.cancelled[state.strategy]?'The unfilled remainder is cancelled.':'60 remain open. Review the remaining quantity.'}</p>${link('Review order','order/IC1042','text-link','arrow')}</div></div>`)}</div>
 ${section('12 highest-ranked stocks',`${s.name} ranking · ${state.strategy==='long'?'quality, valuation, growth, and evidence':state.strategy==='swing'?'momentum, structure, volume, and catalysts':'liquidity, relative volume, and session strength'}`,rankTable(),link('Explore all stocks','explore','text-link'),'flush')}</div>`;return dashboardHeading()+`<div class="dashboard-content">${withComparison(content)}</div>`;}
function explore(){return title(`${strategy().name} stock research`,strategy().lead,link('Open Comparison','compare','btn','layers'),'EXPLORE STOCKS')+`<div class="stack">${rankingTimeline()}<div class="card"><form id="stock-filters" class="filter-bar" style="margin:0"><input class="field" id="stock-search" aria-label="Search by company, symbol, or industry" placeholder="Search company, symbol, or industry…" value="${esc(exploreQuery)}"><select class="field" id="sector-filter" aria-label="Industry"><option value="">All industries</option>${[...new Set(stockData.map(c=>c.sector))].map(x=>`<option ${x===exploreSector?'selected':''}>${x}</option>`).join('')}</select><select class="field" id="score-filter" aria-label="Minimum model score"><option value="0">All model scores</option>${[80,85,90].map(v=>`<option value="${v}" ${v===Number(exploreScore)?'selected':''}>${v}+</option>`).join('')}</select>${action('Clear','clear-filters','btn small')}</form></div><div class="card flush"><div class="card-header"><div><h2>Ranked opportunities</h2><p id="stock-count">${strategy().name} · ${snapshotLabel()}</p></div></div><div id="ranking-results">${explorationRankingTable()}</div><div id="stock-empty" hidden>${empty('No matching companies','Remove a filter or search a different company.',action('Clear filters','clear-filters'))}</div><p class="ranking-data-note">Ranking review: <span id="ranking-review-label">${snapshotLabel()}</span>. Prices are quoted as of ${asOf}.</p></div></div>`;}
const companyTabs=c=>[['Overview',`company/${c.id}/overview`,'overview'],['Financials',`company/${c.id}/financials`,'financials'],['Technicals',`company/${c.id}/chart`,'chart'],['News & events',`company/${c.id}/news`,'news'],['Risks & evidence',`company/${c.id}/risks`,'risks'],['Peers',`company/${c.id}/peers`,'peers']];
function priceChart(c){return section('Price & technical context',`${c.name} · ${asOf}`,`<div class="row between wrap" style="margin-bottom:18px">${rangeControls()}<div class="row"><label class="small">Chart type<select class="field compact-select" id="chart-style"><option value="candle" ${state.chartStyle==='candle'?'selected':''}>Candlestick</option><option value="line" ${state.chartStyle==='line'?'selected':''}>Line</option></select></label>${action('Indicators','indicators','btn small')}</div></div>${chart('price','price-'+c.id,c)}<div class="chart-legend"><span><i class="legend-dot"></i>Price</span>${state.indicator==='ema'?'<span><i class="legend-dot" style="background:#c59448"></i>EMA (20)</span>':''}<span>Volume confirmation: ${c.rvol.toFixed(1)}×</span></div>`);}
function fundamentals(c){return section('Fundamental ratios','Business quality, growth, and valuation · FY 2025–26',`<div class="ratio-grid">${[['P/E',c.pe+'×','Price relative to earnings'],['ROE',c.roe+'%','Return on shareholder equity'],['ROCE',c.roce+'%','Return on capital employed'],['Revenue growth',c.growth+'%','Year-on-year revenue change'],['Debt / equity',c.debt===null?'Sector-specific':c.debt+'×','Financial leverage'],['Operating margin',c.margin+'%','Operating profit / revenue']].map(([l,v,n])=>`<div><span class="small muted">${l}</span><strong>${v}</strong><small>${n}</small></div>`).join('')}</div>`,action('Understand these ratios','definitions','btn small'));}
function technicals(c){const vw=c.price*.995;return section('Technical ratios & levels',`${strategy().name} context · inspect the conditions before an entry`,table(['Indicator','Value','What it means'],[['RSI (14)',c.rsi,'Momentum strength; not a standalone entry signal'],['EMA (20)',fixed(c.price*.986),'Short-term trend reference'],['EMA (50)',fixed(c.price*.967),'Intermediate trend reference'],['EMA (200)',fixed(c.price*.91),'Long-term trend reference'],['VWAP',fixed(vw),'Volume-weighted session price'],['Relative volume',c.rvol.toFixed(1)+'×','Volume compared with its usual level'],['ATR (14)',fixed(c.atr),'Average price range; informs risk distance'],['MACD','Positive','Momentum direction'],['Support',fixed(c.price-c.atr*1.5),'Price area to monitor'],['Resistance',fixed(c.price+c.atr*1.8),'Potential price barrier']].map(row=>`<tr>${row.map((v,i)=>`<td>${i===0?`<strong>${v}</strong>`:v}</td>`).join('')}</tr>`)),'','flush');}
function companyPage(id,tab='overview'){const c=stock(id),score=scores(c),chosen=selected().includes(c.id);let body='';
 if(tab==='overview')body=`${priceChart(c)}${section('AI research assessment',`${strategy().name} · ${score.total}/100`, `<h3>${c.catalyst}</h3><p style="margin-top:9px">${rationale(c)}</p><div class="source-card"><strong>Why consider this stock?</strong><p>${c.reason}</p></div><div class="comparison-risk"><strong>What could change the view?</strong><p>${c.risk}</p></div>`,action('View model breakdown','model-breakdown','btn small',`data-id="${c.id}"`))}${fundamentals(c)}${technicals(c)}`;
 else if(tab==='financials')body=`${fundamentals(c)}${section('Financial statements','₹ crore · annual consolidated reporting',financialTable(c),'','flush')}`;
 else if(tab==='chart')body=`${priceChart(c)}${technicals(c)}${section('Entry conditions',strategy().name,conditionList(c))}`;
 else if(tab==='news')body=section('Company news & events','Read the event, source context, and its implications.',newsCards([c]));
 else if(tab==='risks')body=`${section('Risks and decision boundaries','Review the opposing evidence',`<div class="risk-message"><h3>${c.risk}</h3><p>Check the effect on valuation, thesis validity, and your allowed position size before acting.</p></div>${lines([['Entry invalidation',fixed(c.price-c.atr*1.5)],['Stock weight limit','Policy controlled'],['News catalyst',c.catalyst],['Evidence date','23 Oct 2026']])}<h3 style="margin-top:20px">Source interpretation</h3><p style="margin-top:9px">${c.reason} This supports research consideration; entry timing and risk checks are evaluated separately.</p>`,action('Open evidence','source','btn small',`data-id="${c.id}"`))}${section('Condition checks','Clear status and the next step',conditionList(c))}`;
 else body=compareTable([c,...stockData.filter(x=>x.sector===c.sector&&x.id!==c.id),...ranked().filter(x=>x.id!==c.id)].filter((x,i,a)=>a.findIndex(y=>y.id===x.id)===i).slice(0,3));
 return `<div class="breadcrumb">${link('Explore stocks','explore','')} / ${c.name}</div>${title(c.name,`${c.id} · ${c.sector} · ${strategy().name}`,`${action(state.watch.includes(c.id)?'In watchlist':'Add to watchlist','watch','btn',`data-id="${c.id}"`)}${link('Open Execution','plan/selections','btn primary','plan')}`,'STOCK RESEARCH')}<div class="stock-price-bar"><strong>${fixed(c.price)}</strong><span class="positive">${pct(c.change)}</span><span class="small muted">${asOf} · End-of-day</span>${action('Add to comparison','add-compare','btn small',`data-id="${c.id}"`)}</div>${tabs(companyTabs(c),tab)}${withComparison(`<div class="stack">${body}</div>`)}`;
}
function conditionList(c){return [['Research eligibility','Meets screening criteria','green'],['Trend / momentum',c.technical>=85?'Aligned':'Further confirmation required',c.technical>=85?'green':'amber'],['Relative volume',`${c.rvol.toFixed(1)}× average`,''],['AI selection',aiPickStocks().picks.includes(c.id)?'In current AI picks':'Not in current AI picks',aiPickStocks().picks.includes(c.id)?'green':''],['Automation',state.accepted[state.strategy]?'Active':'Ready to execute',state.accepted[state.strategy]?'green':'amber'],['New entries',state.paused[state.strategy]?'On hold':'Subject to risk checks',state.paused[state.strategy]?'red':'']].map(([a,b,t])=>`<div class="condition"><span>${a}</span>${badge(b,t)}</div>`).join('');}
function financialTable(c){const revenue=[1200,1350,1480,1480*(1+c.growth/100)],margins=[c.margin-2.8,c.margin-2,c.margin-1.1,c.margin],operating=revenue.map((v,i)=>v*margins[i]/100),net=operating.map(v=>v*.68),cash=net.map(v=>v*1.13);return table(['Metric','FY 2022–23','FY 2023–24','FY 2024–25','FY 2025–26'],[['Revenue',...revenue],['Operating profit',...operating],['Net profit',...net],['Operating cash flow',...cash]].map(([name,...v])=>`<tr><td><strong>${name}</strong></td>${v.map(x=>`<td>${x.toLocaleString('en-IN',{maximumFractionDigits:1})}</td>`).join('')}</tr>`));}
function compareTable(list=state.comparison[state.strategy].map(stock)){return section(`${strategy().name} comparison`,'Aligned inputs, model results, catalysts, and risks',list.length?table(['Metric',...list.map(company)],[['Model score',...list.map(c=>scores(c).total+'/100')],['Price',...list.map(c=>fixed(c.price))],['Business quality',...list.map(c=>scores(c).quality+'/100')],['Valuation',...list.map(c=>scores(c).value+'/100')],['Technical strength',...list.map(c=>scores(c).technical+'/100')],['Event assessment',...list.map(c=>scores(c).event+'/100')],['RSI',...list.map(c=>c.rsi)],['Relative volume',...list.map(c=>c.rvol+'×')],['Revenue growth',...list.map(c=>c.growth+'%')],['ROE',...list.map(c=>c.roe+'%')]].map(row=>`<tr>${row.map((v,i)=>`<td>${i===0?`<strong>${v}</strong>`:v}</td>`).join('')}</tr>`)):empty('Choose stocks to compare','Select up to three companies.',action('Choose companies','compare-picker','btn primary')),action('Choose companies','compare-picker','btn small'),'flush');}
function compare(){const list=state.comparison[state.strategy].map(stock).sort((a,b)=>scores(b).total-scores(a).total);return title('Comparison',`${strategy().name} · Model review: ${snapshotLabel()}`,`${action(icon('plus')+'Add more stocks','compare-picker','btn primary')}${action('Clear comparison','clear-comparison','btn')}`,'WORKSPACE COMPARISON')+`<div class="comparison-workspace">${comparisonPool()}<div class="stack comparison-work-area">${comparisonSlots()}${compareTable(state.comparison[state.strategy].map(stock))}<div class="comparison-rationale-grid">${list.map((c,i)=>section(c.name,`${i===0?'Highest':'Next'} assessment · ${scores(c).total}/100`,`<h3>Why consider it?</h3><p style="margin-top:9px">${rationale(c)}</p><div class="comparison-risk"><strong>Risk / invalidation</strong><p>${c.risk}</p></div>${link('Review full research',`company/${c.id}/overview`,'text-link','arrow')}`)).join('')}</div>${info('The assessment is specific to '+strategy().name+'. Review the research and risk conditions before selecting a stock for your stock selection.')}</div></div>`;}
const planTabs=[['Selected stocks','plan/selections','selections'],['Stock actions','plan/actions','actions']];
function automationScope(){return section('Handled automatically','After you press Execute, the AI runs every remaining step for this strategy.',`<div class="automation-scope">${[['search','Stock selection','Top model-ranked names for the strategy'],['wallet','Position sizing','Whole shares within your budget, with a cash buffer'],['clock','Entry timing','Enters only when the entry trigger is met'],['shield','Risk checks','Concentration, funds, and quote freshness before each order'],['chart','Targets & exits','Stop-loss, reward-to-risk target, and trailing exits'],['orders','Order routing','Orders sent to your broker and reconciled']].map(([ico,name,copy])=>`<div class="automation-scope-item"><span>${icon(ico)}</span><div><strong>${name}</strong><small>${copy}</small></div></div>`).join('')}</div>`);}
function positionLadder(rows){if(!rows.length)return `<p class="field-help">No open positions yet. Entries appear here once the AI fills them.</p>`;return `<div class="ladder-list">${rows.map(r=>{const span=r.targetPx-r.stopPx||1,entryPos=Math.max(0,Math.min(100,(r.entry-r.stopPx)/span*100));return `<div class="ladder-row"><div class="ladder-head"><a href="#/holding/${r.stock.id}">${esc(r.stock.name)}</a><span class="${toneClass(r.pnl)}">${signedMoney(r.pnl)} · ${pct(r.retPct)}</span></div><div class="ladder-track" role="img" aria-label="${esc(r.stock.name)}: stop-loss ${fixed(r.stopPx)}, entry ${fixed(r.entry)}, now ${fixed(r.price)}, target ${fixed(r.targetPx)}"><span class="ladder-fill ${r.price>=r.entry?'pos':'neg'}" style="left:${Math.min(entryPos,r.progress).toFixed(2)}%;width:${Math.abs(r.progress-entryPos).toFixed(2)}%"></span><i class="ladder-entry" style="left:${entryPos.toFixed(2)}%" title="Entry ${fixed(r.entry)}"></i><i class="ladder-now" style="left:${r.progress.toFixed(2)}%" title="Now ${fixed(r.price)}"></i></div><div class="ladder-scale"><span>${r.stopPx>r.initialStop+1e-9?'Trailing stop':'Stop'} ${fixed(r.stopPx)}</span><span>Entry ${fixed(r.entry)} → now ${fixed(r.price)}</span><span>Target ${fixed(r.targetPx)}</span></div></div>`;}).join('')}<div class="ladder-key"><span><i class="ladder-key-entry"></i>Entry price</span><span><i class="ladder-key-now"></i>Current price</span><span>Left edge = trailing stop-loss (rises with the price) · right edge = target</span></div></div>`;}
function stockActionsView(acts){const enteredValue=acts.entered.reduce((a,r)=>a+r.value,0),waitingValue=acts.waiting.reduce((a,r)=>a+r.value,0);
 return `<div class="stack">${actionCounters(acts)}<div class="grid four">${metric('Capital in positions',money(enteredValue),`${acts.entered.length} entered ${acts.entered.length===1?'stock':'stocks'}`,'layers')}${metric('Waiting allocation',money(waitingValue),`${acts.waiting.length} pending ${acts.waiting.length===1?'entry':'entries'}`,'clock')}${metric('Open Profit/Loss',`<span class="${toneClass(acts.open)}">${signedMoney(acts.open)}</span>`,'Entered positions at latest price','chart')}${metric('Realized from exits',`<span class="${toneClass(acts.realized)}">${signedMoney(acts.realized)}</span>`,`${acts.exited.length} closed trades · before charges`,'wallet')}</div>
 ${acts.blocked?info(acts.blocked+'. No new entries are placed'+(killActive()&&killState().exit?' and open positions are exiting at market':'')+'.','paused-status'):acts.paused?info('New entries are on hold until you press Execute again. Open positions keep their trailing stop-loss and target.','paused-status'):''}
 ${section('AI performance',`${strategy().name} · closed trades and return versus the Nifty 50 reference`,aiScorecardView(),rangeControls())}
 ${section('Entered · holding now',`Trailing stop-loss ${acts.settings.stop}% below each position's highest price · target +${acts.targetPct.toFixed(1)}% from entry`,positionLadder(acts.entered)+(acts.entered.length?table(['Company','Qty','Entry','Now','Trailing stop','Target','Profit/Loss','AI management'],acts.entered.map(r=>{const m=aiManage(r);return `<tr><td>${company(r.stock)}</td><td>${r.qty}</td><td>${fixed(r.entry)}</td><td>${fixed(r.price)}</td><td><strong>${fixed(r.stopPx)}</strong>${r.stopPx>r.initialStop+1e-9?`<small class="muted trail-from">from ${fixed(r.initialStop)}</small>`:''}</td><td>${fixed(r.targetPx)}</td><td class="${toneClass(r.pnl)}"><strong>${signedMoney(r.pnl)}</strong><small class="muted"> ${pct(r.retPct)}</small></td><td>${r.exitQueued?badge('Exit queued · kill switch','red'):`<span class="ai-manage">${esc(m.note)}<small>${esc(m.next)}</small></span>`}</td></tr>`;})):''))}
 ${section('Waiting for entry',`AI picks not yet held · budget ${money(acts.settings.budget)}`,acts.waiting.length?table(['Company','Confidence','Entry trigger','Qty','Allocation','Initial stop','Target','Status'],acts.waiting.map(r=>`<tr><td>${company(r.stock)}</td><td>${confChip(r.confidence)}</td><td>${r.triggerLabel} <strong>${fixed(r.trigger)}</strong></td><td>${r.qty}</td><td>${money(r.value)}</td><td>${fixed(r.stopPx)}</td><td>${fixed(r.targetPx)}</td><td>${badge(r.status,/hold|kill|Halted/i.test(r.status)?'red':'amber')}</td></tr>`)):`<p class="field-help">Every AI pick is already held. New candidates appear after the next model review.</p>`,'','flush waiting-card')}
 ${section('Exited',`Closed by the AI · realized ${signedMoney(acts.realized)} before charges`,barList(acts.exited.map(x=>({label:esc(x.stock.name),value:x.pnl})),{signed:true,format:signedMoney})+table(['Company','Qty','Entry','Exit','Profit/Loss','Return','Reason','Closed'],acts.exited.map(x=>`<tr><td>${company(x.stock)}</td><td>${x.qty}</td><td>${fixed(x.entry)}</td><td>${fixed(x.exit)}</td><td class="${toneClass(x.pnl)}"><strong>${signedMoney(x.pnl)}</strong></td><td class="${toneClass(x.retPct)}">${pct(x.retPct)}</td><td>${badge(x.reason,x.reason==='Stop-loss hit'?'red':x.reason==='Target reached'?'green':'')}</td><td>${x.date}</td></tr>`)))}
 ${section('AI decision log','Every action the AI took or skipped, and why.',aiDecisionLog())}</div>`;}
function plan(tab='selections'){const s=strategy(),view=['actions','monitoring'].includes(tab)?'actions':'selections',paused=state.paused[state.strategy];const blocked=automationBlocked(),status=blocked?badge(blocked,'red'):paused?badge('Automation paused','red'):state.accepted[state.strategy]?badge('Automation active','green'):badge('Ready to execute','amber');const body=view==='actions'?stockActionsView(stockActions()):`<div class="stack">${tradeMode()==='paper'?info('Paper mode · the AI runs the full strategy with virtual orders. Switch to Live when you are ready.','warning'):''}${oneClickExecute()}${aiBrainCard()}</div>`;return title(`${s.name} execution`,'Enter your budget and stop-loss. The AI selects, enters, and exits automatically.',paperToggle()+status,'EXECUTION')+tabs(planTabs,view)+body;}
function holdingsTable(){return table(['Company','Quantity','Average cost','Market price','Market value','Profit/Loss',''],holdings().map(h=>{const gain=(h.stock.price-h.cost)*h.qty;return `<tr><td>${company(h.stock)}</td><td>${h.qty}</td><td>${fixed(h.cost)}</td><td>${fixed(h.stock.price)}</td><td>${money(h.stock.price*h.qty)}</td><td class="${toneClass(gain)}">${signedMoney(gain)}</td><td>${link('Details',`holding/${h.stock.id}`,'text-link')}</td></tr>`;}));}
function portfolio(){const a=account(),acts=stockActions(),sectors=industryRows(),cashWeight=a.cash/a.equity*100;
 const allocation=[{label:'Invested exposure',value:a.invested,display:money(a.invested),color:'var(--brand)'},{label:'Reserved within cash',value:a.reserved,display:money(a.reserved),color:'#c59448'},{label:'Available cash',value:a.available,display:money(a.available),color:cashColor}];
 const industry=[...sectors.map(r=>({label:esc(r.sector),value:r.weight})),{label:'Cash',value:cashWeight,color:cashColor}];
 return title(`${strategy().name} portfolio`,`Holdings source: account snapshot · ${asOf}`,link('Performance breakdown','performance','btn','chart'),'PORTFOLIO')+`<div class="stack"><div class="grid four">${metric('Account equity',money(a.equity),'Market value + cash','portfolio')}${metric('Positions at market',money(a.invested),`Cost basis ${money(a.cost)}`,'layers')}${metric('Profit/Loss',`<span class="${toneClass(a.unrealized)}">${signedMoney(a.unrealized)}</span>`,'Market value − cost basis','chart')}${metric('Total cash',money(a.cash),`${money(a.available)} available + ${money(a.reserved)} reserved`,'wallet')}</div>${section(state.strategy==='intraday'?'Session positions':'Holdings',`${broker().name} •• 1042 · ${asOf}`,holdingsTable(),link('Review allocation','rebalance','text-link'),'flush')}
 <div class="grid equal portfolio-charts">${section('Capital allocation','Allocated capital, invested exposure, and available cash.',donutChart(allocation,money(a.equity),'Account equity','Capital allocation')+lines([['Allocated capital',money(a.capital)],['Net profit added',`<span class="${toneClass(a.net)}">${signedMoney(a.net)}</span>`],['Account equity',money(a.equity)]]))}${section('Industry exposure','Portfolio weight uses current account equity.',barList(industry,{format:v=>v.toFixed(2)+'%',max:Math.max(...industry.map(r=>r.value))})+`<p class="field-help">Industries plus cash add up to ${(sectors.reduce((s,r)=>s+r.weight,0)+cashWeight).toFixed(2)}% of ${money(a.equity)}.</p>`)}</div>
 ${section('Profit/Loss by position','Open positions · latest price versus average cost',barList(holdings().map(h=>({label:`<a href="#/holding/${h.stock.id}">${esc(h.stock.name)}</a>`,value:h.qty*(h.stock.price-h.cost)})).sort((x,y)=>y.value-x.value),{signed:true,format:signedMoney})+`<p class="field-help">Entries, exits and each position's trailing stop are in ${link('Stock actions','plan/actions','text-link')}.</p>`)}</div>`;}
function holdingPage(id){const c=stock(id),h=holdings().find(h=>h.stock.id===c.id);if(!h)return title(c.name,'This company is not held in the selected strategy.',link('Open research',`company/${c.id}/overview`,'btn primary'),'POSITION DETAIL')+empty('No current position','Choose the appropriate strategy or inspect the company research.',link('Return to portfolio','portfolio','btn'));return `<div class="breadcrumb">${link('Portfolio','portfolio','')} / ${c.name}</div>${title(c.name,`${strategy().name} position · ${broker().name}`,link('Full stock research',`company/${c.id}/overview`,'btn'),'POSITION DETAIL')}<div class="stack"><div class="grid four">${metric('Quantity',h.qty,'Shares','portfolio')}${metric('Average cost',fixed(h.cost),'Per share','report')}${metric('Market value',money(c.price*h.qty),'Current quantity × price','wallet')}${metric('Profit/Loss',signedMoney((c.price-h.cost)*h.qty),'Before allocation of account charges','chart')}</div>${priceChart(c)}<div class="grid equal">${section('Investment / trade rationale',strategy().name,`<p>${rationale(c)}</p><div class="comparison-risk"><strong>What could invalidate the view?</strong><p>${c.risk}</p></div>`)}${section('Risk & protection','Review authority alongside condition checks.',conditionList(c))}</div>${fundamentals(c)}${technicals(c)}</div>`;}
function rebalance(){const a=account(),h=holdings()[0],reduce=Math.max(1,Math.floor(h.qty*.1));return title('Review allocation changes','Current holdings, proposed changes, and the permission boundary.',link('Back to portfolio','portfolio','btn'),'PORTFOLIO REVIEW')+`<div class="grid two"><div class="stack">${section('Proposed change','Reduce concentration and retain the released allocation as cash.',table(['Company','Current quantity','Proposed quantity','Cash released'],[`<tr><td>${company(h.stock)}</td><td>${h.qty}</td><td>${h.qty-reduce}</td><td>${money(reduce*h.stock.price)}</td></tr>`]),'','flush')}${section('Impact and authority','Execution depends on agreement scope and risk checks.',lines([['Current stock weight',(h.qty*h.stock.price/a.equity*100).toFixed(2)+'%'],['Proposed stock weight',((h.qty-reduce)*h.stock.price/a.equity*100).toFixed(2)+'%'],['Released allocation',money(reduce*h.stock.price)],['New replacement stock','None'],['Automation',planStatus()]]))}</div>${section('Next step','Review the allowed reduction and exit scope.',`<p>Reallocation should be evaluated with transaction costs, the current thesis, and permitted actions.</p><div class="stack" style="margin-top:20px">${link('Open execution','plan/selections','btn primary')}${action('Mark review complete','review-complete','btn')}</div>`)}</div>`;}
const orderList=()=>[
 {id:'IC1042',stock:stock(ranked()[0].id),qty:100,filled:40,status:state.cancelled[state.strategy]?'Cancelled remainder':'Partially filled',side:'Buy'},
 {id:'IC1041',stock:stock(ranked()[1].id),qty:50,filled:50,status:'Filled',side:'Buy'},
 {id:'IC1040',stock:stock(ranked()[2].id),qty:25,filled:0,status:'Rejected',side:'Buy'},
 {id:'IC1039',stock:stock(ranked()[3].id),qty:20,filled:0,status:'Cancelled',side:'Buy'}
];
function orderStage(o){const rejected=o.status==='Rejected',filled=o.status==='Filled',open=o.status==='Partially filled',cancelled=o.status.includes('Cancelled');if(rejected)return{label:'Blocked at risk/permission gate',tone:'red',step:'2 of 4'};if(cancelled)return{label:'Stopped · remainder cancelled',tone:'amber',step:'4 of 4'};if(filled)return{label:'Completed · quantity filled',tone:'green',step:'4 of 4'};if(open)return{label:'In progress · partially filled',tone:'amber',step:'3 of 4'};return{label:'Awaiting broker acknowledgement',tone:'amber',step:'3 of 4'};}
function ordersTable(filter='all'){const list=orderList().filter(o=>filter==='all'||filter==='open'&&o.status==='Partially filled'||filter==='completed'&&o.status==='Filled'||filter==='cancelled'&&o.status.includes('Cancelled')||filter==='rejected'&&o.status==='Rejected');return list.length?table(['Company','Side','Requested','Filled','Model stage','Status',''],list.map(o=>{const st=orderStage(o);return `<tr><td>${company(o.stock)}</td><td>${badge(o.side,'green')}</td><td>${o.qty}</td><td>${o.filled} / ${o.qty}</td><td><span class="order-stage-cell">${badge(st.step,st.tone)}<small>${st.label}</small></span></td><td>${badge(o.status,o.status==='Filled'?'green':o.status==='Rejected'?'red':'amber')}</td><td>${link('View order',`order/${o.id}`,'text-link')}</td></tr>`;})):empty('No orders in this view','Choose another status to inspect the order history.',link('All orders','orders','btn'));}
function orderProgress(o){const rejected=o.status==='Rejected',filled=o.status==='Filled',open=o.status==='Partially filled',steps=[['Model check',rejected?'Needs review':'Complete',rejected?'alert':'done'],['Risk & permission gate',rejected?'Blocked':'Passed',rejected?'alert':'done'],['Broker acknowledgement',rejected?'Rejected':open?'Partially acknowledged':filled?'Accepted':'Awaiting broker',rejected?'alert':open?'progress':filled?'done':'pending'],['Quantity filled',`${o.filled} of ${o.qty} shares`,filled?'done':open?'progress':'pending']];return `<div class="order-progress-list">${steps.map(([label,value,status],i)=>`<div class="order-progress-step ${status}"><span class="order-step-number">${i+1}</span><div><strong>${label}</strong><p>${value}</p></div></div>`).join('')}</div><div class="source-card"><strong>${rejected?'Why this needs attention':open?'In progress':filled?'Order completed':'Waiting for an update'}</strong><p>${rejected?'The broker rejected this request. Review the rejection reason and verify price, available funds, and order permissions before deciding what to do next.':open?`${o.filled} shares have filled. ${o.qty-o.filled} remain open with the broker. Monitor the remaining quantity and its current status.`:filled?'The broker reports the requested quantity filled. Check the position and transaction record.':'The request is waiting for broker acknowledgement. No completion is assumed until a broker state is received.'}</p></div>`;}
function ordersPage(filter='all'){const open=orderList().filter(o=>o.status==='Partially filled').length,rejected=orderList().filter(o=>o.status==='Rejected').length;const active=orderList().filter(o=>o.status==='Partially filled'||o.status==='Rejected');return title('Orders',`${strategy().name} · ${broker().name} •• 1042 · ${asOf}`,action('Export CSV','export-orders','btn',''),'EXECUTION')+`<div class="grid three order-status-summary">${metric('In progress',open,'Broker acknowledgement / fills','clock')}${metric('Needs attention',rejected,'Rejected by broker','shield')}${metric('Execution path','Model → risk → broker','Each stage is visible per order','orders')}</div>`+section('Live model execution','What the model is doing right now for orders that are in progress or need attention. Each card shows the four execution stages and where the order currently stands.',active.length?`<div class="orders-live-grid">${active.map(o=>{const st=orderStage(o);return `<article class="orders-live-card ${st.tone}"><div class="row between wrap">${company(o.stock)}${badge(o.status,o.status==='Rejected'?'red':'amber')}</div>${orderProgress(o)}<div class="row wrap" style="margin-top:14px">${link('Open order detail',`order/${o.id}`,'btn small')}</div></article>`;}).join('')}</div>`:`<div class="orders-live-empty">${icon('check')}<p>No orders are in progress or blocked right now. Completed and cancelled orders are listed below.</p></div>`)+`<div class="orders-tabs">`+tabs([['All','orders','all'],['Open','orders/open','open'],['Completed','orders/completed','completed'],['Cancelled','orders/cancelled','cancelled'],['Rejected','orders/rejected','rejected']],filter)+`</div>`+section('Order history','Requested quantity is distinct from filled quantity. Status reflects the latest broker state available to the platform.',ordersTable(filter),'','flush');}
function orderPage(id){const o=orderList().find(x=>x.id===id)||orderList()[0],remain=o.status==='Partially filled'?o.qty-o.filled:0;return title(`Order ${o.id}`,`${o.stock.name} · ${strategy().name} · ${broker().name}`,badge(o.status,o.status==='Filled'?'green':o.status==='Rejected'?'red':'amber'),'ORDER DETAIL')+`<div class="stack">${section('Model → broker execution progress','Each step explains what happened and what to review next.',orderProgress(o))}<div class="grid two">${section('Execution summary','Filled and remaining quantities are accounted for separately.',lines([['Requested quantity',o.qty+' shares'],['Filled quantity',o.filled+' shares'],['Open remaining quantity',remain+' shares'],['Limit price',fixed(o.stock.price)],['Filled value',money(o.filled*o.stock.price)],['Cancelled quantity',o.status.startsWith('Cancelled')?(o.qty-o.filled)+' shares':'0 shares']])+`${remain?`<div style="margin-top:20px">${action('Cancel remaining '+remain+' shares','cancel-order','btn danger',`data-id="${o.id}"`)}</div>`:''}`)}${section('Model & order context','Review what initiated the request and which checks applied.',lines([['Strategy',strategy().name],['Stock',o.stock.name+' · '+o.stock.id],['Model assessment',scores(o.stock).total+'/100'],['Research signal',rationale(o.stock)],['Broker account',broker().name+' •• 1042'],['Agreement','Version 1.0'],['Order intent',o.id],['Last update','23 Oct 2026 · 15:30 IST']])+`<div style="margin-top:20px">${link('Company research',`company/${o.stock.id}/overview`,'text-link')}</div>`)}</div></div>`;}
function risk(){const detail=state.riskDetail==='details'?'details':'overview',descriptions={overview:'Kill switch, safety limits, and first actions.',details:'Causes, evidence, and responses for individual issues.'},condition=state.riskCondition!=='account';return title('Risk & alerts',descriptions[detail],'','ACCOUNT SAFETY')+`<div class="stack"><div class="risk-controls"><div class="risk-depth" role="tablist" aria-label="Risk views">${[['overview','Overview'],['details','Details']].map(([key,label])=>`<button id="risk-tab-${key}" role="tab" aria-selected="${detail===key}" aria-controls="risk-panel" tabindex="${detail===key?'0':'-1'}" class="btn ${detail===key?'primary':''}" data-action="risk-detail" data-detail="${key}">${label}</button>`).join('')}</div><label class="risk-condition-label">Review response workflow<select id="risk-condition" class="field">${[['account','Current account'],['connection','Connection interrupted'],['quotes','Quotes delayed'],['loss','Loss limit exceeded']].map(([key,label])=>`<option value="${key}" ${state.riskCondition===key?'selected':''}>${label}</option>`).join('')}</select></label></div>${condition?info('Selected response workflow: '+({connection:'broker connection interrupted',quotes:'quotes delayed',loss:'loss limit exceeded'})[state.riskCondition]+'. Account figures remain the current ledger values. Open Details to inspect the required response.','warning'):''}<div id="risk-panel" role="tabpanel" tabindex="0" aria-labelledby="risk-tab-${detail}">${detail==='details'?riskDetails():riskOverview()}</div></div>`;}
function watchlist(){const groups=[...new Set(state.watch.map(id=>stock(id).sector))];return title('Watchlist','Find a saved stock, review its current signal, or add another company under its industry.',action('Add company','watch-picker','btn primary'),'RESEARCH COLLECTION')+`<div class="stack"><div class="card watchlist-search-card"><label class="label" for="watchlist-search">Search your saved stocks</label><div class="watchlist-search-row">${icon('search')}<input id="watchlist-search" class="field" value="${esc(state.watchQuery)}" placeholder="Company, symbol, or industry…"><span id="watchlist-result-count" class="small muted"></span></div></div><div class="watchlist-grid">${groups.map(group=>{const list=state.watch.map(stock).filter(c=>c.sector===group);return section(group,`${list.length} ${list.length===1?'company':'companies'}`,table(['Company','Price','Model score','Research signal','Actions'],list.map(c=>`<tr class="watch-stock-row" data-watch-stock="${c.id}"><td>${company(c)}</td><td>${fixed(c.price)}</td><td>${scores(c).total}/100</td><td>${badge(c.technical>=85?'Trend aligned':'Awaiting confirmation',c.technical>=85?'green':'amber')}</td><td><div class="row">${action('Compare','compare-security','btn small',`data-id="${c.id}"`)}${action('Remove','watch','text-link',`data-id="${c.id}"`)}</div></td></tr>`)),action('Add stock in '+group,'watch-group-add','btn small',`data-sector="${esc(group)}"`),'flush industry-group').replace('class="card flush industry-group"','class="card flush industry-group" data-industry-group="'+esc(group)+'"');}).join('')||section('Your watchlist','',empty('Add your first company','Search by company or symbol. Industry groups are created automatically.',action('Add companies','watch-picker','btn primary')))}<p id="watchlist-no-results" class="field-help" hidden>No saved stocks match this search. Clear the search or add a company.</p></div></div>`;}
const events=stockData.map((c,i)=>({id:c.id,company:c,title:c.catalyst,description:c.reason,type:i%3===0?'Company announcement':i%3===1?'Quarterly results':'Contract & business update',date:'23 Oct 2026',time:(9+i%6)+':'+(i%2?'45':'15')+' IST'}));
function newsCards(companies=stockData){const ids=new Set(companies.map(c=>c.id));return [...events].filter(e=>ids.has(e.id)).sort((a,b)=>parseInt(b.time)-parseInt(a.time)||b.time.localeCompare(a.time)).map(e=>`<article class="news-item" data-id="${e.id}"><div class="row between wrap"><span class="eyebrow">${e.type.toUpperCase()}</span><span class="small muted">${e.date} · ${e.time}</span></div><h3 style="margin:10px 0">${e.company.name}: ${e.title.toLowerCase()}</h3><p>${e.description}</p><div class="row between wrap" style="margin-top:16px">${link('Read analysis',`event/${e.id}`,'text-link','arrow')}${badge(e.company.sector)}</div></article>`).join('');}
function news(){const count=holdings().length;return title('News & events','Read current company updates or focus on stocks you own.',action('Refresh all news','refresh-news','btn'),'MARKET INTELLIGENCE')+`<div class="stack"><section class="card holdings-news-card"><div class="row"><span class="next-icon">${icon('portfolio')}</span><div><h2>${newsScope==='holdings'?'News for your holdings':'All company news'}</h2><p>${count} owned stocks in ${strategy().name} · switch views without losing your search.</p></div></div>${newsScope==='holdings'?action('Show all news','refresh-news','btn primary'):action('Show my holdings news','holdings-news','btn primary')}</section><form class="filter-bar" id="news-search" role="search"><input id="news-query" name="q" class="field" aria-label="Search news by company, sector, or keyword" placeholder="Search company, industry, event, or keyword…" value="${esc(newsQuery)}"><select id="news-sector" class="field" aria-label="Filter news by industry"><option value="">All industries</option>${[...new Set(stockData.map(c=>c.sector))].map(s=>`<option ${s===newsSector?'selected':''}>${s}</option>`).join('')}</select><select id="news-type" class="field" aria-label="Event type"><option value="">All events</option>${[...new Set(events.map(e=>e.type))].map(s=>`<option ${s===newsType?'selected':''}>${s}</option>`).join('')}</select><button class="btn primary" type="submit">Search news ${icon('search')}</button>${action('Reset filters','clear-news','btn')}</form>${section(newsScope==='holdings'?'Updates for stocks you own':'Latest available company updates',newsScope==='holdings'?`${strategy().name} positions only · choose “Show all news” to restore all companies.`:'Ordered newest first. Search or filter to narrow the list.',`<p id="news-count" class="small muted" style="margin-bottom:15px"></p><div id="news-results">${newsCards()}</div><div id="news-empty" hidden>${empty('No matching news','Try another company, or refresh to restore all available updates.',action('Show all news','refresh-news'))}</div>`)}</div>`;}
function eventPage(id){const e=events.find(x=>x.id===id)||events[0],c=e.company;return `<div class="breadcrumb">${link('News & events','news','')} / ${c.name}</div>${title(`${c.name}: ${e.title.toLowerCase()}`,`${e.type} · ${e.date} · ${e.time}`,link('Company research',`company/${c.id}/overview`,'btn'),'EVENT ANALYSIS')}<div class="grid two"><div class="stack">${section('What happened',e.type,`<p>${c.reason}</p>`)}${section(`${strategy().name} implication`,'Event-specific analysis',`<p>${rationale(c)}</p><h3 style="margin-top:20px">Why consider it?</h3><p style="margin-top:9px">The event supports the research thesis when considered alongside valuation, market structure, and allocation limits.</p><div class="comparison-risk"><strong>What could weaken the case?</strong><p>${c.risk}</p></div>`)}</div>${section('Evidence & next steps','Keep research distinct from entry authorization.',lines([['Company',c.name],['Industry',c.sector],['Published',e.date+' · '+e.time],['Strategy',strategy().name],['Model assessment',scores(c).total+'/100']])+`<div class="stack" style="margin-top:20px">${link('Review stock details',`company/${c.id}/overview`,'btn primary')}${action('Add to comparison','add-compare','btn',`data-id="${c.id}"`)}</div>`)}</div>`;}
function drawdown(values){let peak=values[0],worst=0;for(const value of values){peak=Math.max(peak,value);worst=Math.min(worst,(value-peak)/peak*100);}return Math.abs(worst);}
function performance(){const a=account(),series=historySeries(),rangeReturn=(series.at(-1)/series[0]-1)*100;return title('Performance',`${strategy().name} · ${broker().name} •• 1042 · ${asOf}`,link('Create performance report','reports','btn primary','report'),'RETURNS & ATTRIBUTION')+`<div class="stack"><div class="grid four">${metric('Net P&L since allocation',signedMoney(a.net),'Realized profit + Profit/Loss − charges','chart')}${metric('Return on allocated capital',pct(a.returnPct),'Net P&L / allocated capital','portfolio')}${metric('Selected-period change',pct(rangeReturn),`${state.range[state.strategy]} · equity series, no external flows`,'pulse')}${metric('Selected-period drawdown',drawdown(series).toFixed(2)+'%','Largest fall from a prior peak','shield')}</div>${section('Account equity history','Account equity includes invested market value and cash.',chart('equity','performance-chart'),rangeControls())}<div class="grid equal">${section('Profit reconciliation','Every number uses the same account ledger.',lines([['Allocated capital',money(a.capital)],['Realized P&L',signedMoney(a.realized)],['Profit/Loss',signedMoney(a.unrealized)],['Charges','−'+money(a.charges)],['Net P&L',signedMoney(a.net)],['Closing equity',money(a.equity)]]))}${section('Return methodology','Definitions you can inspect.',`<div class="source-card"><strong>Net P&L</strong><p>Realized gains + current open-position gains − account charges.</p></div><div class="source-card"><strong>Return on allocated capital</strong><p>Net P&L divided by original allocated capital. Deposits are not counted as profit.</p></div><div class="source-card"><strong>Selected-period change</strong><p>Closing equity / opening equity − 1 for the selected chart range. No external cash flows are included in this account series.</p></div>`)}</div>${section('Open-position contribution','Per-position gain excludes account-level realized gains and charges.',holdingsTable(),'','flush')}</div>`;}
function reportData(kind='Portfolio summary'){
 const a=account();return {kind,strategy:strategy().name,broker:broker().name,account:'•• 1042',asOf,rankingAsOf:snapshotLabel(),period:state.range[state.strategy],generated:new Date().toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}),metrics:a,series:historySeries(),positions:holdings().map(h=>({name:h.stock.name,sector:h.stock.sector,qty:h.qty,cost:h.cost,price:h.stock.price,value:h.qty*h.stock.price,gain:h.qty*(h.stock.price-h.cost)})),rankings:ranked().map(c=>({name:c.name,score:scores(c).total,catalyst:c.catalyst,summary:rationale(c),risk:c.risk})),orders:orderList().map(o=>({id:o.id,name:o.stock.name,qty:o.qty,filled:o.filled,price:o.stock.price,status:o.status}))};
}
function reports(){return title('Reports','Branded account reports with charts, portfolio details, and model assessments.',action('Generate report','generate-report','btn primary'),'ACCOUNT DOCUMENTS')+`<div class="stack"><div class="grid three">${[['Portfolio summary','Holdings, cash, allocation, and profit reconciliation.','portfolio'],['Performance review','Equity graph, return calculations, and contribution.','chart'],['Order history','Order status, filled quantities, prices, and execution details.','orders']].map(([name,desc,i])=>`<article class="card"><span class="feature-icon">${icon(i)}</span><h2>${name}</h2><p class="small" style="margin:10px 0 20px">${desc}</p>${action('Generate '+name.toLowerCase(),'create-report','btn small',`data-kind="${name}"`)}</article>`).join('')}</div>${section('Report history','Each report retains the strategy, broker, and figures used when it was generated.',state.reports.length?table(['Report','Strategy','Broker','Created','Actions'],state.reports.map((r,i)=>`<tr><td>${esc(r.kind)}</td><td>${r.strategy}</td><td>${r.broker}</td><td>${esc(r.generated)}</td><td>${link('Open report',`report/${i}`,'text-link')}</td></tr>`)):empty('Generate your first report','Choose a report type to view its chart and underlying records.',action('Generate report','generate-report','btn primary')),'','flush')}</div>`;}
function reportSeriesSVG(r){const v=r.series,min=Math.min(...v)*.998,max=Math.max(...v)*1.002;const d=v.map((x,i)=>(i?'L':'M')+(35+i*555/(v.length-1)).toFixed(1)+','+(210-(x-min)/(max-min)*170).toFixed(1)).join(' ');return `<svg class="chart" viewBox="0 0 660 250" role="img" aria-label="${r.strategy} account equity graph ending ${money(r.metrics.equity)}"><path d="M35 40H590M35 125H590M35 210H590" class="chart-grid"/><path d="${d}" class="chart-line"/><text x="603" y="44">${(max/100000).toFixed(2)}L</text><text x="603" y="214">${(min/100000).toFixed(2)}L</text><text x="35" y="240">Period opening</text><text x="520" y="240">23 Oct 2026</text></svg>`;}
function reportContent(r){const a=r.metrics;return `<div class="report-document"><header class="report-brand">${logo('home')}<div><strong>${esc(r.kind)}</strong><p>${r.strategy} · ${r.broker} ${r.account}</p><p>Quotes as of ${r.asOf}</p><p>Model review: ${r.rankingAsOf||r.asOf}</p></div></header><div class="grid four">${metric('Closing equity',money(a.equity),'Positions + cash','portfolio')}${metric('Net P&L',signedMoney(a.net),'After charges','chart')}${metric('Capital return',pct(a.returnPct),'Since allocation','pulse')}${metric('Available cash',money(a.available),'Excludes reservations','wallet')}</div>${section('Equity history',`${r.period} · closing equity ${money(a.equity)}`,reportSeriesSVG(r))}${section('Account reconciliation','Amounts in INR',lines([['Allocated capital',money(a.capital)],['Realized P&L',signedMoney(a.realized)],['Profit/Loss',signedMoney(a.unrealized)],['Charges','−'+money(a.charges)],['Closing equity',money(a.equity)],['Positions at market',money(a.invested)],['Total cash',money(a.cash)],['Reserved within cash',money(a.reserved)],['Available cash',money(a.available)]]))}${section(r.kind==='Order history'?'Execution details':'Position details',r.strategy,r.kind==='Order history'?table(['Order','Company','Requested','Filled','Status'],r.orders.map(o=>`<tr><td>${o.id}</td><td>${o.name}</td><td>${o.qty}</td><td>${o.filled}</td><td>${o.status}</td></tr>`)):table(['Company','Quantity','Average cost','Market price','Market value','Profit/Loss'],r.positions.map(p=>`<tr><td>${p.name}</td><td>${p.qty}</td><td>${fixed(p.cost)}</td><td>${fixed(p.price)}</td><td>${money(p.value)}</td><td>${signedMoney(p.gain)}</td></tr>`)),'','flush')}${section('Strategy model ranking','Top 12 companies for the strategy selected when this report was generated.',table(['Rank','Company','Model score','Catalyst'],r.rankings.map((c,i)=>`<tr><td>${i+1}</td><td>${c.name}</td><td>${c.score}/100</td><td>${c.catalyst}</td></tr>`)),'','flush')}<p class="small muted">Generated ${esc(r.generated)} IST · Net P&L = realized profit + Profit/Loss − charges. Model scores are research assessments, not probabilities of profit.</p></div>`;}
function reportPage(id){const r=state.reports[Number(id)];if(!r)return title('Report not found','Generate a report from the selected account.',link('Go to reports','reports','btn primary'));return title(esc(r.kind),`${r.strategy} · ${r.broker} · generated ${esc(r.generated)} IST`,`${action('Download PDF','download-pdf','btn primary',`data-report="${id}"`)}${action('Download CSV','download-report-csv','btn',`data-report="${id}"`)}${action('Print / Save as PDF','print-report','btn',`data-report="${id}"`)}`,'REPORT DETAIL')+reportContent(r);}
function brokerSetup(){const choice=state.pendingBroker||state.broker||'zerodha',perms=currentPermissions(choice);return `<div class="broker-setup-wrap"><div class="eyebrow">YOUR ACCOUNT · YOUR PERMISSIONS</div><h1 tabindex="-1">Choose your broker</h1><p>Select an account provider, then review exactly what the workspace may access.</p><form data-form="broker" class="broker-setup-layout"><section class="card broker-selection"><div class="card-header"><div><h2>Broker accounts</h2><p>Choose from ${Object.keys(brokers).length} account providers.</p></div></div><label class="label" for="broker-search">Find your broker</label><input id="broker-search" class="field" placeholder="Search by broker name…" value="${esc(brokerQuery)}"><div class="broker-grid">${Object.entries(brokers).map(([key,b])=>`<label class="broker-choice" data-broker-choice="${key}"><input type="radio" name="broker" value="${key}" ${choice===key?'checked':''}><span class="broker-monogram" style="background:${b.color}">${b.name[0]}</span><strong>${b.name}</strong><small>${b.product}</small></label>`).join('')}</div><p id="broker-no-results" class="field-help" hidden>No matching broker. Try another name.</p></section><aside class="card broker-permissions"><div class="card-header"><div><h2>Account permissions</h2><p id="permission-broker-name">${brokers[choice].name} · permissions for this account</p></div></div><h3 class="permission-group-title">Execution access</h3><p class="field-help">Choose what the AI may do on this account.</p><label class="permission-line execution-permission permission-select-all"><input type="checkbox" id="permission-all" ${perms.orders&&perms.modify&&perms.automation?'checked':''}><span><strong>Allow all</strong><small>Tick once to allow every execution permission below.</small></span></label>${[['orders','Place orders','Allow the AI to submit orders after risk checks.'],['modify','Modify or cancel orders','Allow changes to unfilled quantities. Requires order access.'],['automation','Strategy automation','Allow the AI to enter and exit within your budget and stop-loss.']].map(([key,name,desc])=>`<label class="permission-line execution-permission"><input type="checkbox" name="${key}" id="permission-${key}" ${perms[key]?'checked':''} ${key!=='orders'&&!perms.orders?'disabled':''}><span><strong>${name}</strong><small>${desc}</small></span></label>`).join('')}<div class="permission-mode" id="permission-mode">${perms.orders?'Execution permissions selected':'Read-only workspace · order submission off'}</div><label class="check-line authorize-line"><input type="checkbox" id="broker-authorized" name="authorized" required><span>I am authorized to use this account and have reviewed these permissions.</span></label><p class="field-help">You can review these permissions later in Settings.</p><button class="btn primary" type="submit" style="width:100%;margin-top:18px">Save permissions & open dashboard ${icon('arrow')}</button></aside></form></div>`;}
function brokerPermissionEditor(){const p=currentPermissions();return `<div class="grid two"><div class="stack">${section('Account access','Reading your account never grants permission to submit orders.',lines([['Balances & available funds','Read access'],['Holdings & positions','Read access'],['Order history','Read access'],['Selected broker',broker().name+' · account •• 1042']]))}${section('Before you enable execution','Order access still depends on risk checks, available funds, and the broker connection.',`<p>Automation follows only the budget and stop-loss you set in Execution. You can turn these permissions off later; open orders and holdings still need separate review.</p><div style="margin-top:16px">${link('Open execution','plan/selections','btn')}</div>`)}</div><form class="card permission-editor" data-form="broker-permissions"><h2>Execution access</h2><p>Choose which actions this application may request from ${broker().name}. Reading your account never grants order authority.</p><label class="permission-line execution-permission permission-select-all"><input type="checkbox" id="exec-select-all" ${p.orders&&p.modify&&p.automation?'checked':''}><span><strong>Enable all execution access</strong><small>Tick to turn on every execution permission below at once.</small></span></label><label class="permission-line execution-permission"><input type="checkbox" name="orders" ${p.orders?'checked':''}><span><strong>Place orders</strong><small>Allow the AI to submit orders after risk checks.</small></span></label><label class="permission-line execution-permission"><input type="checkbox" name="modify" ${p.modify?'checked':''} ${p.orders?'':'disabled'}><span><strong>Modify or cancel orders</strong><small>Allow changes to unfilled quantities. Requires order access.</small></span></label><label class="permission-line execution-permission"><input type="checkbox" name="automation" ${p.automation?'checked':''} ${p.orders?'':'disabled'}><span><strong>Strategy automation</strong><small>Allow the AI to enter and exit within your budget and stop-loss.</small></span></label><div class="permission-mode">${p.orders?'Order access is on · subject to risk checks':'Read-only account · order submission is off'}</div><label class="check-line"><input type="checkbox" name="reviewed" required><span>I reviewed these permissions and understand pause, revocation, and broker disconnection effects.</span></label><button class="btn primary" type="submit">Save execution permissions</button></form></div>`;}
function brokerPage(tab='connection'){const aggregate=Object.keys(strategyList).map(key=>account(key)).reduce((x,a)=>{for(const k of ['equity','invested','cash','available','reserved','capital'])x[k]=(x[k]||0)+a[k];return x;},{});return title(`${broker().name} & capital`,`Account ${broker().prefix} •• 1042 · ${broker().product}`,link('Change broker','connect-broker','btn'),'BROKER ACCOUNT')+tabs([['Account connection','broker','connection'],['Strategy capital','broker/capital','capital'],['Permissions','broker/permissions','permissions']],tab)+(tab==='permissions'?brokerPermissionEditor():`<div class="grid two">${section(tab==='capital'?'Strategy allocation':`${broker().name} account`,tab==='capital'?'Separate budgets for Long-term, Swing, and Intraday.':`${broker().product} · selected account`,tab==='capital'?lines(Object.entries(strategyList).map(([key,s])=>[s.name,money(state.budgets[key])]))+`<div style="margin-top:22px">${link('Edit '+strategy().name+' budget','plan/selections','btn primary')}</div>`:`<div class="broker-identity"><span class="broker-monogram" style="background:${broker().color}">${broker().name[0]}</span><div><h2>${broker().name}</h2><p>${broker().product} · ${broker().prefix} •• 1042</p></div></div>${lines([['Account owner',esc(state.displayName)],['Account context','Indian cash equities'],['Selected strategies','Long-term · Swing · Intraday'],['Last account statement',asOf]])}<div style="margin-top:22px">${link('Open execution','plan/selections','btn')}</div>`)}${section('Account capital summary','Combined capital across all three strategy allocations.',lines([['Allocated capital',money(aggregate.capital)],['Account equity',money(aggregate.equity)],['Positions at market',money(aggregate.invested)],['Total cash',money(aggregate.cash)],['Reserved within cash',money(aggregate.reserved)],['Unreserved cash',money(aggregate.available)]])+`<div style="margin-top:18px">${link('Edit execution permissions','broker/permissions','text-link')}</div>`)}</div>`);}
function strategiesPage(){return title('Strategies','Three dedicated approaches. One connected account.','','INVESTMENT & TRADING')+`<div class="grid three">${Object.entries(strategyList).map(([key,s])=>section(s.name,s.horizon,`<span class="feature-icon">${icon(s.icon)}</span><p>${s.lead}.</p>${lines([['Review',s.review],['Allocated capital',money(s.capital)],['Model emphasis',key==='long'?'Quality & valuation':key==='swing'?'Momentum & structure':'Liquidity & session strength']])}<div class="stack" style="margin-top:22px"><a class="btn primary" href="#/home" data-strategy="${key}">Open ${s.name} dashboard ${icon('arrow')}</a>${link('Read strategy rules',`strategy/${key}`,'btn')}</div>`)).join('')}</div>`;}
function strategyPage(key){const s=strategyList[key]||strategyList.long;return title(s.name+' strategy',s.lead,'','STRATEGY RULES')+`<div class="grid two">${section('Selection, entry, and review',s.review,`<div class="number-list">${[['Research',key==='long'?'Business quality, growth, valuation, and material events.':key==='swing'?'Trend, consolidation, relative volume, and catalysts.':'Liquidity, VWAP alignment, relative volume, and session structure.'],['Selection','The client chooses each security. Watchlists and rankings do not authorize trading.'],['Entry','Selected security, valid agreement, fresh conditions, allocation, and risk checks.'],['Exit and review',key==='intraday'?'Session cutoff, protective exits, closeout reconciliation, and residual-position handling.':key==='swing'?'Setup invalidation, holding-period review, and protective exits.':'Thesis review, concentration control, cost-aware rebalancing, and protective exits.']].map(([a,b],i)=>`<div><span class="step-number">${i+1}</span><div><h3>${a}</h3><p>${b}</p></div></div>`).join('')}</div>`)}${section('Use this strategy','The workspace changes its ranking, metrics, and explanations.',`<div class="stack"><a class="btn primary" href="#/home" data-strategy="${key}">Open ${s.name} dashboard</a><a class="btn" href="#/explore" data-strategy="${key}">Explore ${s.name} stocks</a></div>` )}</div>`;}
function results(){return renderModelResults();}
function activity(){return title('Activity history','Account, strategy, and action details in a readable timeline.','','ACCOUNT RECORDS')+section('Recent activity',`${broker().name} •• 1042`,[['Research updated',ranked()[0].name+' · event and model assessment refreshed.','15:30'],['Order partially filled',state.cancelled[state.strategy]?'IC1042 · 40 filled; remainder cancelled.':'IC1042 · 40 shares filled; 60 remaining.','15:20'],['Plan reviewed',strategy().name+' · '+selected().length+' selected stocks.','14:45'],['Broker selected',broker().name+' · account •• 1042.','09:15']].map(([a,b,t])=>`<div class="timeline-item"><span class="timeline-dot"></span><div><strong>${a}</strong><p>${b}</p></div><time>${t} IST</time></div>`).join(''));}
function welcome(){return `<section class="lp-hero"><div class="lp-hero-main"><div class="eyebrow">INVESTSIGHT CAPITAL</div><h1>Research with purpose.<br><em>Invest with clarity.</em></h1><p class="lp-hero-sub">A connected equity platform for understanding companies, finding opportunities worth researching, and acting on them with defined risk — across long-term, swing and intraday.</p><div class="row lp-hero-cta">${link('Register','register','btn primary','arrow')}${link('How it works','how-it-works','btn')}</div><div class="lp-hero-trust"><span>${icon('search')}Evidence-led research</span><span>${icon('shield')}Defined risk controls</span><span>${icon('portfolio')}Portfolio visibility</span></div></div><aside class="lp-hero-panel" aria-label="Market snapshot"><div class="lp-indices"><div class="lp-index"><span class="muted">Nifty 50</span><b>22,936.75</b><span class="up">&#9650; 237.90 (1.05%)</span></div><div class="lp-index"><span class="muted">Bank Nifty</span><b>54,909.65</b><span class="up">&#9650; 642.25 (1.18%)</span></div></div><p class="lp-status">NSE prices &middot; 15-minute delay &middot; Market closed &middot; 29 Oct 2026</p><div class="lp-quicklinks"><span class="lp-quicklinks-head">Jump straight in</span>${link('Build a stock screen','register','lp-quicklink')}${link('Explore sector maps','register','lp-quicklink')}${link('Run a scan','register','lp-quicklink')}${link('Compare stocks','register','lp-quicklink')}</div></aside></section>`+welcomeExtras()+`<section class="public-section"><div class="next-step"><div><h2>Build a more informed investment process.</h2><p>Register, complete the approval step, then login and choose your broker.</p></div>${link('Register','register','btn primary','arrow')}</div></section>`;}
const googleMark=`<svg class="google-mark" viewBox="0 0 24 24" aria-hidden="true"><path fill="#4285F4" d="M23.5 12.3c0-.8-.1-1.6-.2-2.3H12v4.5h6.5a5.6 5.6 0 0 1-2.4 3.6v3h3.9c2.2-2.1 3.5-5.1 3.5-8.8z"/><path fill="#34A853" d="M12 24c3.2 0 6-1.1 8-2.9l-3.9-3c-1.1.7-2.5 1.2-4.1 1.2-3.1 0-5.8-2.1-6.7-5H1.3v3.1A12 12 0 0 0 12 24z"/><path fill="#FBBC05" d="M5.3 14.3a7.2 7.2 0 0 1 0-4.6V6.6H1.3a12 12 0 0 0 0 10.8z"/><path fill="#EA4335" d="M12 4.8c1.8 0 3.3.6 4.6 1.8l3.4-3.4A12 12 0 0 0 1.3 6.6l4 3.1c.9-2.9 3.6-4.9 6.7-4.9z"/></svg>`;
function auth(route){if(route==='register')return requestAccess();const recovery=route==='recovery';return `<div class="auth-wrap"><div class="card"><div class="eyebrow">INVESTSIGHT CAPITAL</div><h1 tabindex="-1">${recovery?'Reset your password':'Welcome back'}</h1><p>${recovery?'Enter the email address associated with your account.':'Login to continue to your workspace.'}</p>${recovery?'':`<button type="button" class="btn google-login" data-action="google-login">${googleMark}Continue with Google</button><div class="auth-divider" role="separator"><span>or login with email</span></div>`}<form data-form="${route}" style="margin-top:${recovery?'27px':'0'}"><div class="form-group"><label class="label" for="email">Email</label><input class="field" id="email" name="email" type="${recovery?'email':'text'}" placeholder="Enter email" required autocomplete="username"><p id="login-error" class="form-error" role="alert" tabindex="-1" hidden></p></div>${!recovery?'<div class="form-group"><label class="label" for="password">Password</label><div class="password-field"><input class="field" id="password" name="password" type="password" placeholder="Enter your password" required minlength="8" autocomplete="current-password"><button type="button" data-action="password-visibility" data-target="password" aria-label="Show password">Show</button></div></div>':''}<button type="submit" class="btn primary">${recovery?'Continue':'Login'} ${icon('arrow')}</button></form>${!recovery?`<div class="row between wrap" style="margin-top:20px;font-size:12px">${link('Forgot password?','recovery','text-link')}</div>`:`<div style="margin-top:20px;font-size:12px">${link('Back to Login','login','text-link')}</div>`}</div></div>`;}
function publicInfo(route,sub){if(route==='features')return `<div class="public-content">${title('A connected equity platform','Research, strategy, execution visibility, and portfolio review.','','OUR PRODUCT')}<div class="grid equal">${[['Research companies','Business quality, growth, valuation, and material events.'],['Understand price structure','Charts, indicators, volatility, relative volume, and entry conditions.'],['Automate execution','Set a budget and stop-loss; the AI selects, enters, and exits.'],['Monitor results','Positions, order states, return reconciliation, reports, and alerts.']].map(([a,b])=>section(a,'',`<p>${b}</p>`)).join('')}</div><div style="margin-top:25px">${link('Register','register','btn primary')}</div></div>`;
 if(route==='how-it-works')return `<div class="public-content">${title('From understanding to oversight','A clear process with your choices and permissions at its centre.','','HOW IT WORKS')}<div class="grid equal">${[['Create your account','Register. After approval, login and select your broker.'],['Research and compare','Review strategy-specific stock rankings, company evidence, and model assessments.'],['Automate execution','Enter a budget and stop-loss. The AI handles selection, entries, and exits.'],['Monitor and review','Follow conditions, orders, positions, returns, and alerts from your dashboard.']].map(([a,b],i)=>section(a,'',`<span class="step-number">${i+1}</span><p style="margin-top:16px">${b}</p>`)).join('')}</div></div>`;
 if(route==='about')return `<div class="public-content">${title('INVESTSIGHT CAPITAL','Research with purpose. Invest with clarity.','','ABOUT US')}<article class="card article"><h2>Our purpose</h2><p>Make equity research and portfolio decisions easier to understand. We bring financial fundamentals, price context, company events, and strategy rules into one structured workflow.</p><h2>Our approach</h2><p>Clear core tasks with detailed financials, technical indicators, comparison tools, and source-linked explanations available where they help. The client chooses securities and reviews the plan’s permissions.</p><h2>Get in touch</h2><p>Have a question about the platform? Contact our team.</p>${link('Contact us','contact','btn')}</article></div>`;
 if(route==='contact')return `<div class="auth-wrap"><div class="card"><h1 tabindex="-1">Contact us</h1><p style="margin-top:12px">Tell us what you would like to know about INVESTSIGHT CAPITAL.</p><form data-form="contact"><div class="form-group"><label class="label" for="contact-name">Name</label><input class="field" id="contact-name" required></div><div class="form-group"><label class="label" for="contact-email">Email</label><input class="field" id="contact-email" type="email" required></div><div class="form-group"><label class="label" for="contact-message">Your question</label><textarea class="field" id="contact-message" required></textarea></div><button class="btn primary" type="submit">Review enquiry</button></form></div></div>`;
 if(route==='public-help')return `<div class="public-content">${title('Help with getting started','Find your next step.','','HELP')}<div class="card faq">${[['How do I begin?','Register, wait for approval, then login and select your broker.'],['How do the strategies differ?','Long-term emphasizes business quality and valuation; Swing emphasizes momentum and price structure; Intraday emphasizes liquidity and session conditions.'],['Who chooses the stocks?','The AI selects stocks from the model ranking. You set the budget and stop-loss, and can pause automation at any time.']].map(([a,b])=>`<details><summary>${a}</summary><p>${b}</p></details>`).join('')}</div></div>`;
 return `<div class="public-content">${title(sub==='privacy'?'Privacy Policy':sub==='terms'?'Terms of Use':'Risk information','INVESTSIGHT CAPITAL','','PRODUCT INFORMATION')}<article class="card article">${sub==='privacy'?'<h2>Account and preference information</h2><p>Account information, preferences, and financial permissions should be managed with clear purpose, limited access, and appropriate controls.</p><h2>Your control</h2><p>Review profile preferences and agreement permissions in Settings. Broker credentials should only be handled through the broker’s authorized process.</p>':sub==='terms'?'<h2>Platform scope</h2><p>The workspace organizes research, strategy-specific analysis, stock selections, and portfolio oversight. Execution permissions must be explicit, account-specific, and subject to risk controls.</p><h2>Research and decisions</h2><p>Model assessments support research. They do not guarantee outcomes or override eligibility and risk limits.</p>':'<h2>Investment and trading risk</h2><p>Equity prices can fall and liquidity can change. Prior returns, research scores, and positive events do not establish future outcomes.</p><h2>Execution risk</h2><p>Partial fills, delays, disconnections, and price gaps require clear handling. Pausing entries, cancelling pending quantities, and closing positions are distinct actions.</p>'}</article></div>`;}
const learning={start:['Getting started','Research → compare → select → allocate → review permissions → monitor.'],ratios:['Financial ratios explained','P/E relates price to earnings. ROE measures returns on equity. ROCE measures returns on capital employed. Debt and margins add business context.'],indicators:['Technical indicators explained','EMA summarizes trend, RSI summarizes momentum, relative volume measures participation, and ATR describes average price range. No indicator alone authorizes a trade.'],cash:['Cash and allocation','Account equity equals invested market value plus cash. Reserved cash is a subset of cash. Available cash excludes reservations. Strategy budgets are allocations within the broker account.'],risk:['Risk and position sizing','Risk checks combine position size, stop distance, liquidity, concentration, and account funds. They cannot guarantee a fill price or eliminate losses.']};
function learn(){return title('Learn','Understand the concept, then return to your task.','','KNOWLEDGE CENTRE')+`<div class="grid equal">${Object.entries(learning).map(([key,[a,b]])=>section(a,'',`<p>${b}</p><div style="margin-top:20px">${link('Read explanation',`article/${key}`,'text-link','arrow')}</div>`)).join('')}</div>`;}
function article(key){const [a,b]=learning[key]||learning.start;return title(a,'A practical explanation connected to your workspace.',link('Back to Learn','learn','btn'),'LEARNING NOTE')+section(a,'',`<p>${b}</p><div style="margin-top:22px">${link('Explore company research','explore','btn primary')}</div>`);}
const settingsTabs=[['Profile','settings/profile','profile'],['Security','settings/security','security'],['Notifications','settings/notifications','notifications'],['Display','settings/display','display'],['Keyboard shortcuts','settings/shortcuts','shortcuts'],['Agreements & permissions','settings/permissions','permissions'],['Privacy','settings/privacy','privacy'],['Workspace tools','settings/workspace','workspace'],['More & resources','settings/resources','resources'],['Pricing & plans','settings/pricing','pricing'],['Learn','settings/learn','learn'],['Help & support','settings/support','support']];
function settings(tab='profile'){let body='';if(tab==='profile')body=settingsProfile();
 else if(tab==='security')body=settingsSecurity();
 else if(tab==='notifications')body=settingsNotifications();
 else if(tab==='display')body=settingsDisplay();
 else if(tab==='permissions')body=settingsPermissions();
 else if(tab==='privacy')body=`<div class="privacy-stack"><div class="privacy-banner">${icon('lock')}<div><h3>Your data stays on this device</h3><p>This workspace runs entirely in your browser. Your preferences, selections, and watchlist are saved only in this browser's local storage — they are not sent to any server, and this interface makes no network calls.</p></div></div><div class="grid equal">${section('What is stored on this device',"Saved locally so your workspace reopens the way you left it.",lines([['Display name',esc(state.displayName)],['Selected broker',state.broker?broker().name:'Not selected'],['Stock selections',Object.values(state.selections).reduce((n,a)=>n+a.length,0)+' across strategies'],['Watchlist companies',state.watch.length],['Saved alerts',state.alerts.length],['Generated reports',state.reports.length],['Theme & display preferences',({light:'Light',dark:'Dark','pure-dark':'Pure dark'})[state.theme]]]))}${section('What is never stored',"Sensitive credentials are never written to this browser.",`<ul class="privacy-list"><li>${icon('check')}Your password — used only to sign in, never saved.</li><li>${icon('check')}Broker login or API credentials.</li><li>${icon('check')}Any data shared with third parties — there are none.</li></ul><p class="field-help">Production authentication and any server-side data handling are enforced separately by the platform backend.</p>`)}</div>${section('Control your data',"Export a copy for your records, or clear everything stored on this device.",`<p>Downloading gives you a JSON copy of everything this browser has saved. Clearing removes all local preferences, selections, watchlist, alerts, and reports from this device — it cannot be undone.</p><div class="row wrap" style="margin-top:20px">${action(icon('download')+'Download my local data','export-privacy-data','btn')}${action('Clear my data on this device','clear-privacy-data','btn danger')}</div>`)}${section('Policies',"Read how the platform handles information and the associated risks.",`<div class="row wrap">${link('Privacy Policy','legal/privacy','btn')}${link('Terms','legal/terms','btn')}${link('Risk information','legal/risk','btn')}</div>`)}</div>`;
 else if(tab==='workspace')body=`<div class="row wrap" style="margin-bottom:22px">${link('Setup preferences','onboarding','btn')}</div>`+workspaceOrganizer();
 else if(tab==='learn')body=`<div class="grid equal">${Object.entries(learning).map(([key,[a,b]])=>`<article class="card"><h3>${a}</h3><p style="margin:10px 0 16px">${b}</p>${link('Read explanation',`article/${key}`,'text-link')}</article>`).join('')}</div>`;
 else if(tab==='shortcuts')body=settingsShortcuts();
 else if(tab==='resources')body=resourcesPanel();
 else if(tab==='pricing')body=pricingTiers('Pricing & plans','Full access is free through 31 Dec 2026 — no payment details required.');
 else if(tab==='support')body=`<form id="help-search" class="filter-bar"><input class="field" name="q" aria-label="Search help" placeholder="Search cash, orders, agreement…"><button class="btn primary" type="submit">Search help</button></form><div class="stack">${link('Orders & partial fills','order/IC1042','btn')}${link('Cash & allocation','article/cash','btn')}${link('Execution','plan/selections','btn')}${link('Contact support','support/new','btn primary')}</div>`;
 else body=`<p>Manage display preferences and account permissions separately. Signing out returns to the public website.</p><div class="row wrap" style="margin-top:20px">${action('Clear saved preferences','reset-state','btn')}${action('Sign out','signout','btn danger')}</div>`;
 return title('Settings','Account preferences, workspace tools, learning, and support.','','YOUR ACCOUNT')+`<div class="grid settings-layout"><nav class="card settings-nav" aria-label="Settings sections">${settingsTabs.map(([a,r,k])=>link(a,r,tab===k?'active':'')).join('')}</nav>${section(settingsTabs.find(x=>x[2]===tab)?.[0]||'Profile',SETTINGS_INFO[tab]||'',body)}</div>`;
}
function support(mode){if(mode==='new')return title('Contact support','Include the affected account, order, or company.','','HELP & SUPPORT')+`<form data-form="support" class="card" style="max-width:780px"><div class="form-group"><label class="label" for="support-subject">Subject</label><input class="field" id="support-subject" name="subject" required></div><div class="form-group"><label class="label" for="support-message">Describe your question</label><textarea class="field" id="support-message" name="message" required></textarea></div><p class="field-help">Account: ${broker().name} •• 1042 · Strategy: ${strategy().name}</p><button type="submit" class="btn primary" style="margin-top:20px">Review request</button></form>`;return title('Help & support','Search a topic or review the relevant explanation.',link('Contact support','support/new','btn primary'),'SUPPORT')+`<form id="help-search" class="filter-bar"><input class="field" name="q" aria-label="Search help" placeholder="Search cash, orders, agreement…"><button class="btn primary" type="submit">Search help</button></form><div class="grid three">${[['Orders & partial fills','order/IC1042'],['Cash & allocation','article/cash'],['Execution','plan/selections']].map(([a,r])=>section(a,'',link('Open explanation',r,'text-link','arrow'))).join('')}</div>`;}
function searchPage(q){const companies=stockData.filter(c=>searchMatch(q,c.name+' '+c.id+' '+c.sector)),pages=[...mainNav,...toolsNav,...utilityNav].filter(([a,r])=>searchMatch(q,a+' '+r.replaceAll('/',' ')));return title(`Search: ${esc(q)}`,'Companies, industries, and workspace pages that match your search.',link('Edit search','home','btn'),'SEARCH')+`<div class="stack">${section('Stocks',`${companies.length} matches`,companies.length?table(['Company','Industry','Strategy signal','Action'],companies.map(c=>`<tr><td>${company(c)}</td><td>${c.sector}</td><td>${scores(c).total}/100 · ${strategy().name}</td><td>${link('Open research',`company/${c.id}/overview`,'text-link')}</td></tr>`)):empty('No matching stocks','Try a company name, symbol, or industry.',link('Explore stocks','explore','btn')),'','flush')}${section('Pages & tools',`${pages.length} matches`,pages.map(([a,r])=>`<div class="list-line"><strong>${a}</strong>${link('Open',r,'text-link')}</div>`).join('')||'<p>No page or tool matches. Try different words.</p>')}</div>`;}
function sitemap(){return title('Workspace directory','Find a page or continue the investment workflow.','','WORKSPACE')+section('All tools','',`<div class="site-map">${[...mainNav,...toolsNav,...utilityNav,...settingsTabs,['Compare stocks','compare'],['Stock actions','plan/actions'],['Rebalance','rebalance'],['Notifications','notifications']].map(([a,r])=>link(a,r,'')).join('')}</div>`);}
function themeControl(){const names={light:'Light',dark:'Dark','pure-dark':'Pure dark'};return `<details class="theme-picker"><summary aria-label="Appearance: ${names[state.theme]}">${icon(state.theme==='light'?'sun':'moon')}<span>${names[state.theme]}</span></summary><div class="theme-picker-menu" role="group" aria-label="Choose appearance">${Object.entries(names).map(([key,name])=>`<button type="button" data-action="set-theme" data-theme-choice="${key}" aria-pressed="${state.theme===key}"><span class="theme-swatch theme-swatch-${key}" aria-hidden="true"></span><span>${name}</span>${state.theme===key?icon('check'):''}</button>`).join('')}</div></details>`;}
function rankingTimeline(){const t=state.timeline[state.strategy],config=timelineConfig(),point=config.current;let controls='';if(state.strategy==='intraday')controls=`<label>Trading day<input class="field" id="timeline-date" type="date" max="2026-10-23" value="${t.date}"></label><label>Session<select class="field" id="timeline-session"><option value="full" ${t.session==='full'?'selected':''}>Morning → afternoon</option><option value="morning" ${t.session==='morning'?'selected':''}>Morning · 09:15–12:00</option><option value="afternoon" ${t.session==='afternoon'?'selected':''}>Afternoon · 12:00–15:30</option></select></label>`;else if(state.strategy==='swing')controls=`<label>From<input class="field" id="timeline-start" type="date" max="2026-10-23" value="${t.start}"></label><label>To<input class="field" id="timeline-end" type="date" max="2026-10-23" value="${t.end}"></label><span class="timeline-frequency">Daily closing snapshots</span>`;else controls=`<label>Review interval<select class="field" id="timeline-unit"><option value="week" ${t.unit==='week'?'selected':''}>Week</option><option value="month" ${t.unit==='month'?'selected':''}>Month</option><option value="year" ${t.unit==='year'?'selected':''}>Year</option></select></label><label>Periods<input class="field" id="timeline-count" type="number" min="2" max="${t.unit==='year'?10:t.unit==='month'?24:52}" value="${t.count}"></label><label>Through<input class="field" id="timeline-end" type="date" max="2026-10-23" value="${t.end}"></label>`;return `<section class="card ranking-timeline" aria-labelledby="timeline-title"><div class="timeline-heading"><div><h2 id="timeline-title">Ranking timeline</h2><p>Slide through model reviews to see when stocks moved up or down.</p></div><div class="timeline-controls">${controls}</div></div><div class="timeline-slider-row">${action(icon('chevron'),'timeline-back','btn icon-only',`id="timeline-prev" aria-label="Previous ranking snapshot" ${config.position===0?'disabled':''}`)}<div class="timeline-slider"><div class="row between"><span class="small muted">${config.points[0].label}</span><output id="ranking-at" for="ranking-position">${point.full}</output><span class="small muted">${config.points.at(-1).label}</span></div><input id="ranking-position" type="range" min="0" max="${config.points.length-1}" step="1" value="${config.position}" aria-label="Ranking snapshot" aria-valuetext="${point.full}"></div>${action(icon('chevron'),'timeline-forward','btn icon-only',`id="timeline-next" aria-label="Next ranking snapshot" ${config.position===config.points.length-1?'disabled':''}`)}</div><div id="ranking-movement-summary">${rankingMovementSummary()}</div></section>`;}
function rankingMovementSummary(){const moved=rankingMovements().filter(x=>x.change!==0).slice(0,3),reason=state.strategy==='intraday'?'session momentum and volume checks':state.strategy==='swing'?'daily structure and catalyst review':'quality and valuation review';return `<div class="ranking-change-strip">${moved.length?moved.map(m=>`<span><strong>${m.stock.name}</strong><span class="${m.change>0?'positive':'negative'}">${m.change>0?'↑':'↓'} ${m.previous} → ${m.rank}</span><small>${reason}</small></span>`).join(''):'<span>Ranking order unchanged from the previous review.</span>'}</div>`;}
function allVisibleRankedSelected(){const visible=rankingMovements().filter(m=>searchMatch(exploreQuery,m.stock.name+' '+m.stock.id+' '+m.stock.sector)&&(!exploreSector||exploreSector===m.stock.sector)&&scores(m.stock).total>=Number(exploreScore));return visible.length>0&&visible.every(m=>selected().includes(m.stock.id));}
function explorationRankingTable(){const moves=rankingMovements(),col=state.strategy==='long'?'Revenue growth':state.strategy==='swing'?'RSI / ATR':'Relative volume';return table(['Rank','Company','Rank movement','Price',col,'Model score','Actions'],moves.map(m=>{const c=m.stock;return `<tr class="stock-row" data-id="${c.id}"><td>${String(m.rank).padStart(2,'0')}</td><td>${company(c)}</td><td><span class="${m.change>0?'positive':m.change<0?'negative':'muted'}">${m.change>0?'↑ '+m.change:m.change<0?'↓ '+Math.abs(m.change):'—'}</span><small class="rank-previous">Previously #${m.previous}</small></td><td><strong>${fixed(c.price)}</strong><br><small class="${c.change>0?'positive':'negative'}">${pct(c.change)}</small></td><td>${state.strategy==='long'?c.growth.toFixed(1)+'%':state.strategy==='swing'?`${c.rsi} / ${fixed(c.atr)}`:c.rvol.toFixed(1)+'×'}</td><td><div class="score-cell"><strong>${scores(c).total}</strong><span class="score-cell-track"><span style="width:${scores(c).total}%"></span></span></div></td><td><div class="row">${action('Compare','compare-security','btn small',`data-id="${c.id}"`)}${link('Research',`company/${c.id}/overview`,'text-link')}</div></td></tr>`;}));}
function refreshRankingSnapshot(){if(currentRoute!=='explore'){render();return;}const config=timelineConfig();$('#ranking-at').textContent=config.current.full;$('#ranking-position').value=config.position;$('#ranking-position').setAttribute('aria-valuetext',config.current.full);$('#ranking-results').innerHTML=explorationRankingTable();$('#ranking-movement-summary').innerHTML=rankingMovementSummary();$('#ranking-review-label').textContent=config.current.full;$('#timeline-prev').disabled=config.position===0;$('#timeline-next').disabled=config.position===config.points.length-1;filterStocks();}
function placeComparison(id,slot=null){if(!stockData.some(s=>s.id===id))return false;const list=state.comparison[state.strategy],existing=list.indexOf(id);if(existing>=0){if(slot===null)return false;list.splice(existing,1);list.splice(Math.min(slot,list.length),0,id);}else if(slot!==null&&slot<list.length){list[slot]=id;}else if(list.length<6){list.push(id);}else{toast('Compare up to six stocks. Remove one to add another.');return false;}persist();return true;}
function comparisonSlots(){const list=state.comparison[state.strategy];return `<div class="comparison-drop-slots" data-comparison-dropzone="true">${Array.from({length:6},(_,i)=>{const id=list[i],c=id?stock(id):null;return `<section class="comparison-drop-slot ${c?'is-filled':''}" data-drop-slot="${i}" tabindex="0" aria-label="Comparison slot ${i+1}${c?': '+c.name:''}">${c?`<div class="comparison-picked" draggable="true" data-security="${c.id}" aria-label="Drag to reorder ${c.name}"><div class="row between">${company(c)}${action(icon('close'),'remove-compare','btn icon-only small',`data-id="${c.id}" aria-label="Remove ${c.name}"`)}</div><div class="row between" style="margin-top:15px"><strong class="comparison-score">${scores(c).total}<small>/100</small></strong>${badge(strategy().name,'green')}</div><p class="small muted">${fixed(c.price)} · ${c.catalyst}</p></div>`:`<span class="drop-symbol">${icon('plus')}</span><h3>Security ${i+1}</h3><p>Drag a ranked security here<br>or search and select it.</p>${action('Search securities','focus-comparison-search','text-link')}`}</section>`;}).join('')}</div>`;}
function comparisonPool(){return `<aside class="card comparison-source" aria-label="Ranked securities"><div class="card-header"><div><h2>Ranked securities</h2><p>${strategy().name} · 12 model-ranked stocks</p></div>${action('Add more stocks','compare-picker','btn small','plus')}</div><label class="label" for="comparison-search">Search and select</label><div class="comparison-search-field">${icon('search')}<input id="comparison-search" aria-label="Search ranked securities" value="${esc(comparisonQuery)}" placeholder="Company, symbol, or industry…"></div><p class="field-help">Drag a security into a slot, or use Add. Compare up to six stocks.</p><div class="comparison-pool-list">${ranked().map((c,i)=>`<article class="ranked-security" draggable="true" data-security="${c.id}" data-pool-security="${c.id}" aria-label="Rank ${i+1}: ${c.name}; drag to comparison"><span class="security-drag-handle" aria-hidden="true">⠿</span><div class="ranked-security-main"><span class="eyebrow">RANK ${i+1} · ${scores(c).total}/100</span>${company(c)}</div>${action(state.comparison[state.strategy].includes(c.id)?'Added':'Add','add-compare','btn small',`data-id="${c.id}" ${state.comparison[state.strategy].includes(c.id)?'disabled':''}`)}</article>`).join('')}</div><p id="comparison-no-results" class="field-help" hidden>No matching securities. Try another company or industry.</p></aside>`;}
function filterComparisonPool(){const q=comparisonQuery.trim();let count=0;$$('[data-pool-security]').forEach(el=>{const c=stock(el.dataset.poolSecurity),matches=searchMatch(q,c.name+' '+c.id+' '+c.sector);el.hidden=!matches;if(matches)count++;});if($('#comparison-no-results'))$('#comparison-no-results').hidden=count!==0;}
function updateTimelineControl(el){const key=state.strategy,t=state.timeline[key],previous={...t};if(el.id==='timeline-unit'){t.unit=el.value;t.count=Math.min(t.count,t.unit==='year'?10:t.unit==='month'?24:52);}else if(el.id==='timeline-count'){const count=Number(el.value);if(!Number.isFinite(count)||count<2){el.value=t.count;toast('Choose at least two review periods.');return;}t.count=Math.min(Math.floor(count),t.unit==='year'?10:t.unit==='month'?24:52);}else if(el.id==='timeline-session')t.session=el.value;else{if(!/^\d{4}-\d{2}-\d{2}$/.test(el.value)||el.value>'2026-10-23'){toast('Choose a date on or before 23 Oct 2026.');render();return;}t[el.id.replace('timeline-','')]=el.value;if(key==='swing'&&(t.start>t.end||(new Date(t.end)-new Date(t.start))/86400000>366)){state.timeline[key]=previous;toast('Choose a date range of up to one year, with From before To.');render();return;}}t.position=timelineConfig(key).points.length-1;persist();render();}
function isMobileViewport(){return typeof window.matchMedia==='function'&&window.matchMedia('(max-width:760px)').matches;}
function sidebarExpanded(){return isMobileViewport()?state.mobileSidebarOpen:!state.sidebarCollapsed;}
function permissionDefaults(){return {balances:true,holdings:true,history:true,orders:false,modify:false,automation:false};}
function currentPermissions(key=state.broker){return {...permissionDefaults(),...(state.permissions[key]||{})};}
function filterBrokerChoices(){const q=brokerQuery.toLowerCase().trim();let count=0;$$('[data-broker-choice]').forEach(el=>{const b=brokers[el.dataset.brokerChoice],show=(b.name+' '+b.product).toLowerCase().includes(q);el.hidden=!show;if(show)count++;});if($('#broker-no-results'))$('#broker-no-results').hidden=count>0;}
function refreshPermissionControls(restore=false){const choice=$('input[name="broker"]:checked')?.value||state.pendingBroker||state.broker||'zerodha';state.pendingBroker=choice;const existing=currentPermissions(choice);if(restore){for(const key of ['orders','modify','automation'])$('#permission-'+key).checked=existing[key];$('#broker-authorized').checked=false;}const execution=$('#permission-orders').checked;for(const key of ['modify','automation']){const field=$('#permission-'+key);field.disabled=!execution;if(!execution)field.checked=false;}const allBox=$('#permission-all');if(allBox)allBox.checked=['orders','modify','automation'].every(k=>$('#permission-'+k).checked);$('#permission-mode').textContent=execution?'Order access selected · risk checks still apply':'Read-only workspace · order submission off';$('#permission-broker-name').textContent=brokers[choice].name+' · permissions for this account';}
function requestAccess(){return `<div class="access-request-layout"><section class="access-introduction"><div class="eyebrow">A CONSIDERED START</div><h1 tabindex="-1">Your research.<br>Your decisions.<br><em>Your workspace.</em></h1><p>Bring your broker account into a clear process for research, planning, and portfolio oversight.</p><div class="access-review-steps">${[['1','Register','Create your account and tell us how you plan to use the platform.'],['2','Account review','An administrator reviews your access request.'],['3','Connect your broker','After approval, login and choose account permissions.']].map(([n,a,b])=>`<div class="row"><span class="step-number">${n}</span><div><h3>${a}</h3><p>${b}</p></div></div>`).join('')}</div></section><section class="card access-request-card"><div class="eyebrow">INVESTSIGHT CAPITAL</div><h2>Create your account</h2><p>Access is reviewed before you enter the client workspace.</p><form data-form="request-access" id="request-access-form"><div class="grid equal"><div class="form-group"><label class="label" for="request-name">Full name</label><input class="field" id="request-name" name="name" autocomplete="name" required placeholder="Your full name"></div><div class="form-group"><label class="label" for="request-username">Username</label><input class="field" id="request-username" name="username" required minlength="3" maxlength="30" pattern="(?:[A-Za-z0-9._]|-){3,30}" autocomplete="username" placeholder="Choose a username"></div></div><div class="form-group"><label class="label" for="request-email">Email address</label><input class="field" id="request-email" name="email" type="email" required autocomplete="email" placeholder="you@example.com"></div><div class="form-group"><label class="label" for="request-password">Password</label><div class="password-field"><input class="field" id="request-password" name="password" type="password" required minlength="8" maxlength="128" autocomplete="new-password" aria-describedby="request-password-rules"><button type="button" data-action="password-visibility" data-target="request-password" aria-label="Show password">Show</button></div><div id="request-password-rules" class="password-rules">${[['length','8–128 characters'],['case','Upper & lower case'],['number','At least one number'],['symbol','At least one symbol']].map(([key,label])=>`<span data-password-rule="${key}">${label}</span>`).join('')}</div></div><div class="form-group"><label class="label" for="request-confirm">Confirm password</label><div class="password-field"><input class="field" id="request-confirm" name="confirm" type="password" required autocomplete="new-password"><button type="button" data-action="password-visibility" data-target="request-confirm" aria-label="Show confirm password">Show</button></div><p class="field-help" id="request-password-match" aria-live="polite"></p></div><div class="form-group"><label class="label" for="request-broker">Preferred broker</label><select class="field" id="request-broker" name="broker"><option value="">Choose later</option>${Object.entries(brokers).map(([key,b])=>`<option value="${key}">${b.name}</option>`).join('')}</select></div><fieldset class="access-interest"><legend>What would you like to use?</legend>${Object.entries(strategyList).map(([key,s])=>`<label><input type="checkbox" name="interest" value="${key}">${s.name}</label>`).join('')}</fieldset><label class="check-line"><input type="checkbox" name="terms" required><span>I agree to the <a class="text-link" href="#/legal/terms">Terms</a> and have read the <a class="text-link" href="#/legal/privacy">Privacy Policy</a>.</span></label><button type="submit" class="btn primary" style="width:100%">Create account ${icon('arrow')}</button><p class="field-help" style="margin-top:12px">A request does not enable trading. Administrator approval and broker permissions come first.</p></form><hr class="divider"><p class="small">Already have approved access? ${link('Login','login','text-link')}</p></section></div>`;}
function passwordChecks(value){return {length:value.length>=8&&value.length<=128,case:/[a-z]/.test(value)&&/[A-Z]/.test(value),number:/\d/.test(value),symbol:/[^A-Za-z0-9\s]/.test(value)};}
function refreshPasswordFeedback(){const field=$('#request-password');if(!field)return;const checks=passwordChecks(field.value);$$('[data-password-rule]').forEach(el=>{el.classList.toggle('met',checks[el.dataset.passwordRule]);});const confirm=$('#request-confirm'),matches=!confirm.value||confirm.value===field.value;confirm.setCustomValidity(matches?'':'Passwords must match.');field.setCustomValidity(Object.values(checks).every(Boolean)?'':'Use 8–128 characters with upper and lower case, a number, and a symbol.');$('#request-password-match').textContent=confirm.value?(matches?'Passwords match.':'Passwords do not match.') : '';$('#request-password-match').className='field-help '+(matches?'positive':'negative');}
function accessStatus(){const r=state.accessRequest;if(!r)return title('Register','Create an account to view its approval status.',link('Register','register','btn primary'));const status=r.status||'Pending',heading=status==='Active'?'Your account access is approved.':status==='Suspended'?'Your account access is suspended.':'Your access request is awaiting review.';return `<div class="access-status-wrap"><section class="card"><span class="access-status-icon">${icon(status==='Active'?'check':'clock')}</span><div class="eyebrow">ACCOUNT ACCESS</div><h1 tabindex="-1">${heading}</h1><p>${status==='Active'?'Login with your username to choose your broker and review permissions.':'An administrator reviews access before broker connection and workspace setup.'}</p>${lines([['Request ID',esc(r.id)],['Username',esc(r.username)],['Email',esc(r.emailMasked)],['Status',status==='Pending'?'Awaiting administrator approval':status],['Requested',esc(r.requestedAt)+' IST']])}<div class="access-status-next"><h3>Next step</h3><p>${status==='Active'?'Use Login, then choose account and strategy permissions.':status==='Suspended'?'Contact support if you need a review of your account access.':'Once approved, use Login to connect your broker and review account permissions.'}</p></div><div class="row wrap">${link('Back to Login','login','btn primary')}${link('Contact us','contact','btn')}</div></section></div>`;}

function watchlistPicker(sector=''){watchPickerQuery=sector;showDialog('Add a company to your watchlist',`<form data-form="watch-picker"><label class="label" for="watch-picker-search">Search company, symbol, or industry</label><input class="field" id="watch-picker-search" value="${esc(sector)}" placeholder="Type a company name…"><p class="field-help">Choose one or more companies. Existing companies are marked. New stocks are grouped by industry.</p><div class="row between wrap" style="margin:10px 0"><label class="check-line"><input type="checkbox" id="watch-picker-select-all"><span>Select all matching stocks</span></label><button class="btn small" type="button" data-action="watch-picker-clear">Clear selection</button></div><div class="watch-picker-list">${stockData.map(c=>{const exists=state.watch.includes(c.id);return `<label class="watch-picker-row" data-watch-picker="${c.id}"><input type="checkbox" name="companies" value="${c.id}" ${exists?'checked disabled':''}><span>${stockMark(c)}</span><span><strong>${c.name}</strong><small>${c.id} · ${c.sector}</small></span>${exists?badge('In watchlist','green'):`<span class="small muted">${fixed(c.price)}</span>`}</label>`;}).join('')}</div><p id="watch-picker-empty" class="field-help" hidden>No companies match your search.</p><div class="row between wrap" style="margin-top:18px"><span id="watch-picker-count" class="small muted">0 companies selected</span><button type="submit" class="btn primary">Add selected companies</button></div></form>`);filterWatchlistPicker();}
function filterWatchlistPicker(){const q=watchPickerQuery;let count=0;$$('[data-watch-picker]').forEach(el=>{const c=stock(el.dataset.watchPicker),show=searchMatch(q,c.name+' '+c.id+' '+c.sector);el.hidden=!show;if(show)count++;});if($('#watch-picker-empty'))$('#watch-picker-empty').hidden=count>0;}
function filterWatchlist(){const q=state.watchQuery;let count=0;$$('[data-watch-stock]').forEach(row=>{const c=stock(row.dataset.watchStock);row.hidden=!searchMatch(q,c.name+' '+c.id+' '+c.sector);if(!row.hidden)count++;});$$('[data-industry-group]').forEach(group=>group.hidden=!group.querySelector('[data-watch-stock]:not([hidden])'));if($('#watchlist-result-count'))$('#watchlist-result-count').textContent=`${count} ${count===1?'stock':'stocks'}`;if($('#watchlist-no-results'))$('#watchlist-no-results').hidden=count!==0;}
function riskGauge(label,value,limit,description){const ratio=value/limit*100,tone=ratio>=100?'red':ratio>=80?'amber':'green';return `<div class="risk-gauge"><div class="row between wrap"><strong>${label}</strong>${badge(value.toFixed(2)+'% / '+limit+'% limit',tone)}</div><div class="risk-gauge-track" role="img" aria-label="${label}: ${value.toFixed(2)} percent against ${limit} percent limit"><span class="${tone}" style="width:${Math.max(0,Math.min(100,ratio))}%"></span><i></i></div><div class="risk-gauge-scale"><span>0</span><span>${limit}% limit</span></div><p>${description}</p></div>`;}
function riskSnapshot(){const a=account(),positions=holdings().map(h=>({...h,value:h.qty*h.stock.price,weight:h.qty*h.stock.price/a.equity*100})).sort((x,y)=>y.weight-x.weight),series=historySeries(),dailyLoss=Math.max(0,-a.daily/(a.equity-a.daily)*100),dd=drawdown(series);return {a,positions,dailyLoss,dd,largest:positions[0]};}
function riskIssues(){const {a,largest}=riskSnapshot(),order=orderList()[0],issues=[];if(largest.weight>=strategyConfig().maxWeight*.8)issues.push({level:largest.weight>strategyConfig().maxWeight?'high':'review',heading:largest.stock.name+': position concentration',summary:`${largest.weight.toFixed(2)}% of strategy equity is held in this company. The stock weight limit is ${strategyConfig().maxWeight}%.`,next:'Review the position size before increasing exposure.',id:largest.stock.id,category:'Concentration'});issues.push({level:'review',heading:'Evergreen Consumer: valuation sensitivity',summary:`A P/E of ${stock('EVERGREEN').pe}× makes the investment thesis sensitive to earnings expectations.`,next:'Check earnings growth, margins, and the valuation rationale.',id:'EVERGREEN',category:'Company research'});if(!state.cancelled[state.strategy])issues.push({level:'review',heading:order.stock.name+': partially filled order',summary:`${order.filled} of ${order.qty} shares filled; ${order.qty-order.filled} shares remain open.`,next:'Review the remainder and its price condition. Filled shares remain recorded.',id:order.stock.id,category:'Execution',order:order.id});if(state.strategy==='intraday')issues.push({level:'review',heading:'Session closeout requires review',summary:'Open positions and pending orders need reconciliation before the session ends.',next:'Check quantities and closeout status for every intraday position.',id:largest.stock.id,category:'Session risk'});if(!currentPermissions().orders)issues.push({level:'info',heading:'Order submission is off',summary:'Your account permissions currently allow research and account visibility.',next:'Review execution permissions only when you are ready to authorize orders.',id:largest.stock.id,category:'Account permissions',permissions:true});const response={connection:{heading:'Broker connection interrupted',summary:'Order acknowledgements and account updates may be unavailable.',next:'Pause new entries, reconnect your broker, and reconcile open orders before resuming.'},quotes:{heading:'Quotes are delayed',summary:'A stale price must not be used to authorize a new entry.',next:'Wait for current quotes. Review open exposure and price timestamps.'},loss:{heading:'Daily loss limit exceeded',summary:'The account condition requires new entries to remain blocked.',next:'Review the loss, reconcile positions and orders, and complete the required risk review.'}}[state.riskCondition];if(response)issues.unshift({level:'high',...response,id:largest.stock.id,category:'Immediate attention',response:true});return issues;}
function riskExposureChart(){const {positions}=riskSnapshot(),limit=strategyConfig().maxWeight,max=Math.max(20,limit+5,...positions.map(h=>h.weight));return `<div class="exposure-chart" role="group" aria-label="Position weights as a percentage of strategy equity; limit ${limit} percent"><div class="exposure-axis"><span>Share of strategy equity</span><span>0 → ${max.toFixed(0)}%</span></div>${positions.map(h=>`<div class="exposure-row"><a href="#/company/${h.stock.id}/chart">${h.stock.name}</a><span class="exposure-track"><i style="left:${limit/max*100}%" title="${limit}% position limit"></i><b class="${h.weight>limit?'red':h.weight>=limit*.8?'amber':'green'}" style="width:${h.weight/max*100}%"></b></span><strong>${h.weight.toFixed(2)}%</strong></div>`).join('')}<p class="field-help">Vertical marks show the ${limit}% stock weight limit. Select a company to review its chart.</p></div>`;}

function riskContributionChart(){const {positions}=riskSnapshot(),contributions=positions.map(h=>({...h,gain:h.qty*(h.stock.price-h.cost)})),max=Math.max(1,...contributions.map(h=>Math.abs(h.gain)));return `<div class="contribution-chart" role="group" aria-label="Open-position Profit/Loss contribution; negative values left of zero and positive values right"><div class="contribution-axis"><span>Loss</span><span>0</span><span>Profit</span></div>${contributions.map(h=>`<div class="contribution-row"><a href="#/company/${h.stock.id}/chart">${h.stock.name}</a><span class="contribution-track"><i></i><b class="${h.gain>=0?'green':'red'}" style="${h.gain>=0?'left':'right'}:50%;width:${Math.abs(h.gain)/max*48}%"></b></span><strong class="${h.gain>=0?'positive':'negative'}">${fixed(h.gain)}</strong></div>`).join('')}<p class="field-help">Open positions only. Account-level realized gains and charges are excluded. All rows use the same scale.</p></div>`;}
function navigationLayout(){const all=[...mainNav,...toolsNav],known=new Set(all.map(x=>x[1])),saved=state.navLayout;if(!saved||!Array.isArray(saved.main)||!Array.isArray(saved.tools))return {main:mainNav.map(x=>x[1]),tools:toolsNav.map(x=>x[1])};const seen=new Set(),clean=(items,group)=>items.filter(route=>{if(!known.has(route)||seen.has(route)||group==='tools'&&route==='home')return false;seen.add(route);return true;}),main=clean(saved.main,'main'),tools=clean(saved.tools,'tools');if(!seen.has('home')){main.unshift('home');seen.add('home');}for(const [,route] of all)if(!seen.has(route)){(mainNav.some(x=>x[1]===route)?main:tools).push(route);seen.add(route);}return {main,tools};}
function orderedNavigation(group){const catalog=new Map([...mainNav,...toolsNav].map(item=>[item[1],item]));return navigationLayout()[group].map(route=>catalog.get(route));}
function placeNavigation(route,group,before=null){const layout=navigationLayout(),known=[...layout.main,...layout.tools];if(!known.includes(route)||!['main','tools'].includes(group)||route==='home'&&group==='tools'||before===route)return false;if(before!==null&&!layout[group].includes(before))return false;for(const key of ['main','tools'])layout[key]=layout[key].filter(item=>item!==route);const index=before===null?layout[group].length:layout[group].indexOf(before);layout[group].splice(index,0,route);state.navLayout=layout;persist();return true;}
function moveNavigation(route,delta){if(![-1,1].includes(delta))return false;const layout=navigationLayout(),group=layout.main.includes(route)?'main':layout.tools.includes(route)?'tools':null;if(!group)return false;const index=layout[group].indexOf(route),next=index+delta;if(next<0||next>=layout[group].length)return false;[layout[group][index],layout[group][next]]=[layout[group][next],layout[group][index]];state.navLayout=layout;persist();return true;}
function applyNavigationPreset(key){const preset={research:['home','explore','compare','plan/selections','portfolio','orders','risk'],trading:['home','plan/selections','orders','risk','portfolio','explore','compare'],portfolio:['home','portfolio','performance','risk','reports','explore','plan/selections','orders','compare']}[key];if(key==='default'){state.navLayout=null;persist();return true;}if(!preset)return false;state.navLayout={main:[...preset],tools:[...mainNav,...toolsNav].map(x=>x[1]).filter(route=>!preset.includes(route))};persist();return true;}
function workspaceOrganizer(){return `<div class="stack"><div class="organizer-intro"><div><h3>Make the sidebar work for you</h3><p>Drag items into the order you prefer, or use the arrow buttons. Move less-used pages into More tools. Your changes save automatically on this browser.</p></div>${action('Quick guide','quick-guide','btn small')}</div><div class="navigation-presets" role="group" aria-label="Suggested sidebar arrangements">${[['research','Research first','Explore and compare before execution.'],['trading','Trading first','Execution, orders, and risk within reach.'],['portfolio','Portfolio first','Holdings, performance, and reports together.']].map(([key,name,copy])=>`<button type="button" class="navigation-preset" data-action="nav-preset" data-preset="${key}"><strong>${name}</strong><span>${copy}</span><small>Apply arrangement →</small></button>`).join('')}</div><div class="navigation-organizer">${[['main','Left sidebar'],['tools','More tools']].map(([group,label])=>`<section class="nav-organizer-group" data-nav-group="${group}" aria-label="Arrange ${label}"><div class="row between"><h3>${label}</h3><span class="small muted">${orderedNavigation(group).length} pages</span></div><p class="field-help">${group==='main'?'Keep your frequent pages here.':'Opens in a panel beside the sidebar.'}</p><ol class="nav-organizer-list">${orderedNavigation(group).map(([name,route,ico],index,list)=>`<li class="nav-organizer-row" draggable="true" data-nav-route="${route}" data-nav-group="${group}" aria-label="${name}, position ${index+1} of ${list.length}"><span class="nav-drag-handle" aria-hidden="true">⠿</span><div class="nav-organizer-name">${icon(ico)}<span>${name}</span></div><div class="nav-reorder-buttons">${action('↑','nav-move','btn icon-only small',`data-route="${route}" data-delta="-1" aria-label="Move ${name} up" ${index===0?'disabled':''}`)}${action('↓','nav-move','btn icon-only small',`data-route="${route}" data-delta="1" aria-label="Move ${name} down" ${index===list.length-1?'disabled':''}`)}</div>${route==='home'?'<span class="nav-keep-label">Main page</span>':action(group==='main'?'Move to tools':'Pin to sidebar','nav-group','text-link',`data-route="${route}" data-group="${group==='main'?'tools':'main'}"`)}</li>`).join('')}</ol><div class="nav-drop-end" data-nav-group="${group}" data-nav-end="true">Drop here to move to the end</div></section>`).join('')}</div><div class="row between wrap"><p class="small muted">Dashboard stays in the main navigation. Settings stays at the bottom.</p>${action('Restore default arrangement','nav-preset','btn small','data-preset="default"')}</div></div>`;}
function closeToolsFlyout(restoreFocus=false){state.toolsOpen=false;const panel=$('#sidebar-tool-panel');if(panel)panel.hidden=true;$('.more-tools-toggle')?.setAttribute('aria-expanded','false');const chevron=$('.more-tools-toggle .tools-chevron');if(chevron)chevron.textContent='›';if(restoreFocus)$('.more-tools-toggle')?.focus?.();}
function toolsFlyout(){return `<section class="tools-flyout" id="sidebar-tool-panel" aria-labelledby="tools-panel-title" ${state.toolsOpen?'':'hidden'}><div class="tools-flyout-heading"><div><h2 id="tools-panel-title">More tools</h2><p>Research, account, and reporting tools</p></div>${action(icon('close'),'toggle-tools','btn icon-only small','aria-label="Close More tools"')}</div><nav id="sidebar-tool-links" class="tools-flyout-list" aria-label="More tools">${orderedNavigation('tools').map(navItem).join('')||'<p class="field-help">All tools are pinned to your sidebar.</p>'}</nav><div class="tools-flyout-footer">${link('Arrange sidebar','settings/workspace','text-link','settings')}</div></section>`;}
function dashboardHeading(){return `<div class="page-head dashboard-heading"><div><h1 tabindex="-1">Dashboard</h1><p>${strategy().name} · ${broker().name} ${broker().product} · Account •• 1042</p></div><div class="dashboard-heading-right"><span class="dashboard-quote">Quotes: ${asOf} · NSE cash equities<span class="feed-classification">End-of-day</span></span><div class="row wrap">${link('Open execution','plan/selections','btn small primary','play')}${link('View portfolio','portfolio','btn small','portfolio')}</div></div></div>`;}
function dashboardIntroduction(){if(state.introDismissed)return '';return `<section class="dashboard-introduction" aria-labelledby="intro-title"><div class="intro-topline"><div><span class="eyebrow">START HERE</span><h2 id="intro-title">Your workspace, in three steps</h2></div>${action(icon('close'),'dismiss-intro','btn icon-only small','aria-label="Hide introduction" title="Hide introduction"')}</div><div class="intro-steps"><div><span>1</span><p><strong>Choose your approach</strong>Use Long-term, Swing, or Intraday in the top bar.</p></div><div><span>2</span><p><strong>Research and compare</strong>${link('Explore stocks','explore','text-link')} to review companies and model rankings.</p></div><div><span>3</span><p><strong>Automate execution</strong>In ${link('Execution','plan/selections','text-link')}, enter a budget and stop-loss — the AI selects, enters, and exits.</p></div></div></section>`;}
function quickGuide(){showDialog('A short guide to your workspace',`<p class="guide-lead">Start with one strategy. Every ranking, position, and comparison follows the strategy selected in the top bar.</p><ol class="quick-guide-steps">${[['Choose a strategy','Long-term focuses on business research; Swing on daily setups; Intraday on the current session.','home','Open Dashboard'],['Research before selecting','Explore stocks shows ranked securities. Open a company chart, inspect the evidence, and compare up to six companies.','explore','Explore stocks'],['Automate execution','Enter a budget and stop-loss, then press Execute. The AI selects stocks, enters, and exits; follow it in Stock actions.','plan/selections','Open Execution'],['Monitor what matters','Portfolio shows holdings, Orders shows execution records, and Risk & alerts separates priorities, issue details, and analysis.','risk','Review risk'],['Make it yours','More tools opens beside the sidebar. In Settings → Workspace tools, rearrange pages or pin a tool to the sidebar.','settings/workspace','Arrange sidebar']].map(([name,copy,route,label],i)=>`<li><span class="guide-step-number">${i+1}</span><div><h3>${name}</h3><p>${copy}</p>${link(label,route,'text-link','arrow')}</div></li>`).join('')}</ol><p class="field-help">Open this guide again from Settings → Workspace tools. Learn and Help & support are also in Settings.</p>`);}
function riskHealthBanner(issues){const critical=issues.filter(x=>x.level==='high').length,reviews=issues.filter(x=>x.level==='review').length,condition=state.riskCondition!=='account';return `<section class="risk-health-banner ${critical?'critical':'attention'}"><span class="risk-health-icon">${icon('shield')}</span><div><div class="eyebrow">${critical?'IMMEDIATE ATTENTION':'ACCOUNT REVIEW'}</div><h2>${critical?critical+' high-priority '+(critical===1?'issue':'issues'):reviews+' items to review'}</h2><p>${condition?'Selected response workflow · '+({connection:'broker interruption',quotes:'delayed quotes',loss:'loss limit breach'})[state.riskCondition]:state.paused[state.strategy]?'New entries are paused. Review open orders and positions separately.':'Review the first actions below before increasing exposure.'}</p></div>${badge(critical?'Action required':'Review required',critical?'red':'amber')}</section>`;}
function riskPriorityBadge(level){return badge(level==='high'?'High priority':level==='review'?'Needs review':'Information',level==='high'?'red':level==='review'?'amber':'green');}
function riskOverview(){const {largest,dailyLoss,dd}=riskSnapshot(),issues=riskIssues(),priority={high:0,review:1,info:2},first=[...issues].sort((a,b)=>priority[a.level]-priority[b.level]).slice(0,3);return `<div class="stack risk-overview" data-risk-view="overview">${riskHealthBanner(issues)}${safetyPanel()}<div class="risk-summary-grid">${section('Position concentration','Largest stock / strategy equity',riskGauge(largest.stock.name,largest.weight,strategyConfig().maxWeight,'Check position size as it approaches the limit.'))}${section('Drawdown','Selected equity history',riskGauge('Largest peak-to-trough fall',dd,8,'The largest fall from an earlier equity high.'))}</div>${section('First actions','A short list of what needs attention now.',`<div class="risk-first-actions">${first.map(x=>`<article><div>${riskPriorityBadge(x.level)}<h3>${x.heading}</h3><p>${x.next}</p></div>${link('Review company',`company/${x.id}/risks`,'btn small')}</article>`).join('')}</div>`,action('View all issue details','risk-detail','btn small','data-detail="details"'))}${section('Stock performance alerts','Get notified when a stock you follow moves. Set a price, daily-move, or model-score alert and it will appear here and in Notifications.',`<div class="alert-summary-head"><div><strong>${state.alerts.length} active ${state.alerts.length===1?'alert':'alerts'}</strong><p class="field-help">Alerts never place an order. They only notify you so you can review and decide.</p></div>${action(icon('bell')+'Create an alert','set-alert','btn primary','data-id="'+(state.watch[0]||'ASTER')+'"')}</div>${state.alerts.length?`<div class="alert-summary-list">${state.alerts.slice(0,4).map((x,i)=>`<div class="alert-summary-row"><span class="alert-summary-icon">${icon('bell')}</span><div><strong>${esc(x.company)} · ${esc(x.condition)}</strong><small>${alertThresholdLabel(x)} · ${esc(x.strategy||strategy().name)} · ${esc(alertChannelLabel(x))}</small></div>${action('Remove','remove-alert','btn small danger',`data-index="${i}"`)}</div>`).join('')}</div>${state.alerts.length>4?link('Manage all alerts','risk/details','text-link'):''}`:`<div class="alert-empty-state">${icon('bell')}<p>No alerts yet. Create one to be notified when a stock crosses a price, daily-move, or model-score threshold.</p></div>`}`)}${alertChannelsPanel()}<p class="risk-view-note">Overview gives you the next steps. Open Details for evidence and order context, or Analysis for exposure and return charts.</p></div>`;}
const alertChannelMeta={whatsapp:['WhatsApp','phone','tel','+91 98765 43210','Mobile number with country code'],telegram:['Telegram','send','text','@username','Telegram username'],email:['Email','mail','email','Enter email','Email address']};
function validChannelValue(key,value){const v=String(value||'').trim();return key==='whatsapp'?/^\+?[0-9][0-9\s-]{8,15}$/.test(v):key==='telegram'?/^@?[A-Za-z0-9_]{5,32}$/.test(v):/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v);}
function alertChannelLabel(x){const list=x.channels||(x.notify?['inapp']:[]);return ['In-app',...list.filter(k=>alertChannelMeta[k]).map(k=>alertChannelMeta[k][0])].join(' · ');}
function alertChannelsPanel(){const ch=state.alertChannels||{};return section('Alert delivery','Get alerts on WhatsApp, Telegram, or email as well as in the app.',`<form data-form="alert-channels" class="alert-channels">${Object.entries(alertChannelMeta).map(([key,[name,ico,type,placeholder,label]])=>{const c=ch[key]||{};return `<div class="alert-channel ${c.on?'is-on':''}"><label class="alert-channel-toggle"><input type="checkbox" name="${key}" ${c.on?'checked':''}><span class="alert-channel-icon ${key}">${icon(ico)}</span><span><strong>${name}</strong><small>${c.status?esc(c.status)+(c.requestedAt?' · '+esc(c.requestedAt):''):'Off'}</small></span></label><input class="field" name="${key}-value" type="${type}" placeholder="${placeholder}" aria-label="${label}" value="${esc(c.value||'')}" autocomplete="off"></div>`;}).join('')}<p class="field-help">We send one confirmation message to each selected channel. Alerts start after you confirm it. Alerts never place orders.</p><button class="btn primary" type="submit">${icon('send')}Send notification request</button></form>`);}
function alertThresholdLabel(x){const n=Number(x.threshold);return x.condition.includes('Price')?money(n):x.condition.includes('%')?n+'%':n+' points';}
function riskDetails(){const all=riskIssues(),issues=all.filter(x=>state.riskSeverity==='all'||x.level===state.riskSeverity);return `<div class="stack risk-details" data-risk-view="details">${section('Issue details','Read the cause, affected company, and required response.',`<div class="risk-issue-list">${issues.map(x=>`<article class="risk-issue ${x.level}"><div class="risk-issue-heading">${riskPriorityBadge(x.level)}<span class="small muted">${x.category}</span></div><h3>${x.heading}</h3><p>${x.summary}</p><div class="risk-evidence">${lines([['Scope',strategy().name+' · '+broker().name],['Affected company',stock(x.id).name],['Source',x.response?'Selected response workflow':asOf],['Entry checks',x.response?'Blocked until condition resolved':entryStatus()]])}</div><div class="risk-next"><strong>Required response</strong><p>${x.next}</p></div><div class="row wrap">${link('Review company',`company/${x.id}/risks`,'btn small')}${x.order?link('Review order','order/'+x.order,'text-link'):''}${x.permissions?link('Review permissions','settings/permissions','text-link'):''}${x.response?link('Review broker','broker','text-link'):''}</div></article>`).join('')||'<p>No issues match this priority. Choose All priorities to see every issue.</p>'}</div>`,`<label class="small">Priority<select class="field" id="risk-severity" aria-label="Filter alert priority">${[['all','All priorities'],['high','High priority'],['review','Needs review'],['info','Account information']].map(([key,label])=>`<option value="${key}" ${state.riskSeverity===key?'selected':''}>${label}</option>`).join('')}</select></label>`)}${section('Stock performance alerts','Choose a stock and a price, daily move, or model-score condition. Alerts stay visible here and in Notifications.',`${state.alerts.length?state.alerts.map((x,i)=>`<div class="custom-alert-row"><div><strong>${esc(x.company)} · ${esc(x.condition)}</strong><small>${alertThresholdLabel(x)} · ${x.strategy||strategy().name} · ${esc(alertChannelLabel(x))} · ${esc(x.status||'Active')}</small></div>${action('Remove alert','remove-alert','btn small danger',`data-index="${i}"`)}</div>`).join(''):'<p>No stock-performance alerts yet. Set a threshold for a saved stock or any researched company.</p>'}<div style="margin-top:18px">${action('Create stock alert','set-alert','btn primary','data-id="'+(state.watch[0]||'ASTER')+'"')}</div>`)}${alertChannelsPanel()}</div>`;}
function riskDrawdownChart(){const series=historySeries(),values=[];let peak=series[0];for(const value of series){peak=Math.max(peak,value);values.push((peak-value)/peak*100);}const max=Math.max(10,...values.map(v=>v*1.2)),x=i=>42+i/(values.length-1)*490,y=v=>23+v/max*138,points=values.map((v,i)=>`${x(i).toFixed(1)},${y(v).toFixed(1)}`).join(' ');return `<svg class="risk-drawdown-chart" viewBox="0 0 560 205" role="img" aria-labelledby="risk-dd-title risk-dd-desc"><title id="risk-dd-title">Equity drawdown over ${state.range[state.strategy]}</title><desc id="risk-dd-desc">Drawdown is the percentage below a preceding equity peak. Maximum observed drawdown is ${Math.max(...values).toFixed(2)} percent. The review limit is 8 percent.</desc>${[0,max/2,max].map(v=>`<line x1="42" x2="532" y1="${y(v)}" y2="${y(v)}" stroke="var(--border)"/><text x="33" y="${y(v)+4}" text-anchor="end">${v===0?'0':'−'+v.toFixed(0)}%</text>`).join('')}<line x1="42" x2="532" y1="${y(8)}" y2="${y(8)}" stroke="var(--warning)" stroke-dasharray="5 4"/><text x="530" y="${y(8)-6}" text-anchor="end" class="risk-chart-limit">8% review limit</text><polygon points="42,${y(0)} ${points} 532,${y(0)}" fill="var(--negative)" opacity=".12"/><polyline points="${points}" fill="none" stroke="var(--negative)" stroke-width="2"/><text x="42" y="187">Period start</text><text x="532" y="187" text-anchor="end">${asOf}</text></svg><p class="field-help">${state.range[state.strategy]} equity history · percentage below each preceding peak. A point below the dashed line exceeds the review limit.</p>`;}
function riskScoreBarChart(){const list=ranked().slice(0,6);const max=100;return `<div class="simple-bar-chart" role="group" aria-label="Model score by company, out of 100">${list.map(c=>`<div class="simple-bar-row"><a href="#/company/${c.id}/overview" class="simple-bar-label">${c.name}</a><div class="simple-bar-track"><span class="${scores(c).total>=85?'green':scores(c).total>=75?'amber':''}" style="width:${scores(c).total/max*100}%"></span></div><strong class="simple-bar-value">${scores(c).total}</strong></div>`).join('')}<p class="field-help">Higher bars mean a stronger overall model assessment for ${strategy().name}. A score is research context, not a guarantee of profit.</p></div>`;}

function render(){let route=location.hash.replace(/^#\/?/,'')||'welcome';if(route==='main')return;const base=route.split('/')[0];if(!publicRoutes.includes(base)&&!state.signedIn){route='login';history.replaceState(null,'','#/login');}else if(base==='admin'&&!isAdmin()){route='access-denied';history.replaceState(null,'','#/access-denied');}else if(!publicRoutes.includes(base)&&base!=='admin'&&base!=='access-denied'&&base!=='connect-broker'&&state.signedIn&&!state.broker){route='connect-broker';history.replaceState(null,'','#/connect-broker');}if(state.signedIn&&['recommendations','recommendation'].includes(route.split('/')[0])){route='home';history.replaceState(null,'','#/home');}if(currentRoute!==route)state.toolsOpen=false;currentRoute=route;const [page,a,b]=route.split('/');let content='';switch(page){
 case 'welcome':content=welcome();break;
 case 'admin':content=adminPage(a,b);break;
 case 'access-denied':content=accessDenied();break;
 case 'session-expired':content=sessionExpired();break;
 case 'onboarding':content=clientOnboarding();break;
 case 'request-access':content=requestAccess();break;
 case 'access':content=accessStatus();break;
 case 'login':case 'register':case 'recovery':content=auth(page);break;
 case 'features':case 'how-it-works':case 'about':case 'contact':case 'legal':case 'public-help':content=publicInfo(page,a);break;
 case 'connect-broker':content=brokerSetup();break;
 case 'home':content=dashboard();break;
 case 'explore':content=explore();break;
 case 'company':content=companyPage(a,b||'overview');break;
 case 'compare':content=compare();break;
 case 'plan':content=plan(a||'selections');break;
 case 'portfolio':content=portfolio();break;
 case 'holding':content=holdingPage(a);break;
 case 'rebalance':content=rebalance();break;
 case 'orders':content=ordersPage(a||'all');break;
 case 'order':content=orderPage(a);break;
 case 'risk':content=risk();break;
 case 'watchlist':content=watchlist();break;
 case 'news':content=news();break;
 case 'event':content=eventPage(a);break;
 case 'performance':content=performance();break;
 case 'reports':content=reports();break;
 case 'report':content=reportPage(a);break;
 case 'broker':content=brokerPage(a||'connection');break;
 case 'strategies':content=strategiesPage();break;
 case 'strategy':content=strategyPage(a)+clientStrategyPolicy(a);break;
 case 'results':content=results();break;
 case 'screens':content=stockScreens(a);break;
 case 'analysis':content=analysisPage(a);break;
 case 'sectors':content=sectorsPage(a);break;
 case 'tools':content=toolsPage(a);break;
 case 'pricing':content=pricingPage();break;
 case 'more':content=morePage(a);break;
 case 'activity':content=activity();break;
 case 'learn':content=learn();break;
 case 'article':content=article(a);break;
 case 'settings':content=settings(a||'profile');break;
 case 'support':content=support(a);break;
 case 'notifications':content=notifications();break;
 case 'search':content=searchPage(decodeURIComponent(a||''));break;
 case 'sitemap':content=sitemap();break;
 default:content=title('Page not found','Choose a page from the workspace navigation.',link('Dashboard','home','btn primary'));
 }
 document.documentElement.dataset.theme=state.theme;document.documentElement.dataset.density=prefs().density;document.documentElement.dataset.motion=prefs().reduceMotion?'reduce':'full';document.documentElement.dataset.sidebar=state.sidebarCollapsed?'collapsed':'expanded';document.title=(page==='admin'?'Administration':page==='home'?'Dashboard':page==='plan'?'Execution':page.charAt(0).toUpperCase()+page.slice(1))+' · INVESTSIGHT CAPITAL';
 $('#app').innerHTML=publicRoutes.includes(page)?publicShell(content):page==='admin'&&isAdmin()?adminShell(content):page==='connect-broker'?`<div class="access-shell"><header class="public-header">${logo('welcome')}<div class="public-header-actions">${themeControl()}${action('Sign out','signout','btn')}</div></header><main id="main" class="public-main">${content}</main></div>`:shell(content);
 const chatPane=$('#chat-pane');if(chatPane)chatPane.scrollTop=chatPane.scrollHeight;if(page==='explore')filterStocks();if(page==='news')filterNews();if(page==='compare')filterComparisonPool();if(page==='watchlist')filterWatchlist();if(page==='connect-broker')filterBrokerChoices();if(page==='admin'&&a==='users')filterAdminUsers();if(page==='admin'&&a==='audit')filterAdminAudit();
}
function go(route){if(location.hash==='#/'+route){render();window.scrollTo(0,0);}else location.hash='#/'+route;}
function filterStocks(){const q=exploreQuery;let count=0;$$('.stock-row').forEach(row=>{const c=stock(row.dataset.id),match=searchMatch(q,c.name+' '+c.id+' '+c.sector)&&(!exploreSector||exploreSector===c.sector)&&scores(c).total>=Number(exploreScore);row.hidden=!match;if(match)count++;});if($('#stock-count'))$('#stock-count').textContent=`${count} companies · ${strategy().name} · ${snapshotLabel()}`;if($('#stock-empty'))$('#stock-empty').hidden=count>0;if($('#select-all-ranked'))$('#select-all-ranked').checked=allVisibleRankedSelected();}
function filterNews(){const q=newsQuery.toLowerCase(),owned=new Set(holdings().map(h=>h.stock.id));let count=0;$$('.news-item').forEach(row=>{const e=events.find(x=>x.id===row.dataset.id),match=(newsScope!=='holdings'||owned.has(e.id))&&(e.company.name+' '+e.company.id+' '+e.company.sector+' '+e.title+' '+e.description).toLowerCase().includes(q)&&(!newsSector||e.company.sector===newsSector)&&(!newsType||e.type===newsType);row.hidden=!match;if(match)count++;});if($('#news-count'))$('#news-count').textContent=`${count} ${count===1?'event':'events'} found${newsScope==='holdings'?' · my holdings':''}`;if($('#news-empty'))$('#news-empty').hidden=count>0;}
function invalidateAgreement(){state.accepted[state.strategy]=false;persist();}
function downloadFile(filename,content,mime){const url=URL.createObjectURL(new Blob([content],{type:mime}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csv(rows){return '\uFEFF'+rows.map(row=>row.map(value=>'"'+String(value).replace(/"/g,'""')+'"').join(',')).join('\r\n');}
function reportCSV(r){return [['INVESTSIGHT CAPITAL',r.kind],['Strategy',r.strategy],['Broker',r.broker],['Account',r.account],['Data as of',r.asOf],['Generated',r.generated],['Model ranking review',r.rankingAsOf||r.asOf],[],['Allocated capital',r.metrics.capital],['Closing equity',r.metrics.equity],['Realized P&L',r.metrics.realized],['Profit/Loss',r.metrics.unrealized],['Charges',r.metrics.charges],['Net P&L',r.metrics.net],['Return (%)',r.metrics.returnPct.toFixed(4)],['Total cash',r.metrics.cash],['Reserved cash',r.metrics.reserved],['Available cash',r.metrics.available],[],['Company','Industry','Quantity','Cost','Price','Market value','Profit/Loss'],...r.positions.map(p=>[p.name,p.sector,p.qty,p.cost,p.price,p.value,p.gain]),[],['Equity series index','Account equity'],...r.series.map((v,i)=>[i+1,v]),[],['Rank','Company','Model score','Catalyst','Research summary','Risk'],...r.rankings.map((c,i)=>[i+1,c.name,c.score,c.catalyst,c.summary,c.risk])];}
function comparisonPicker(){showDialog('Add stocks to comparison',`<form data-form="comparison"><p>${strategy().name} · choose up to six companies.</p><div class="form-group"><label class="label" for="compare-picker-search">Find a stock</label><input class="field" id="compare-picker-search" placeholder="Company, symbol, or industry…"></div><div class="picker-list">${ranked().map(c=>`<label class="check-line compare-picker-row" data-compare-picker="${c.id}"><input type="checkbox" name="stock" value="${c.id}" ${state.comparison[state.strategy].includes(c.id)?'checked':''}><span>${c.name}<small class="muted"> · ${scores(c).total}/100 · ${c.sector}</small></span></label>`).join('')}</div><p id="compare-picker-empty" class="field-help" hidden>No stocks match your search.</p><button type="submit" class="btn primary">Update comparison</button></form>`);}
