function getScreenQuery(){const el=$('#screen-query');return el?el.value:(screenState().query[state.strategy]||'');}
function saveScreenQuery(){const el=$('#screen-query');if(el){screenState().query[state.strategy]=el.value;persist();}}
function insertScreenToken(token){const el=$('#screen-query');if(!el)return;const start=el.selectionStart??el.value.length,end=el.selectionEnd??el.value.length,pad=['AND','OR','>','<','+','-','*','/'].includes(token)?' '+token+' ':token+' ';el.value=el.value.slice(0,start)+pad+el.value.slice(end);const pos=start+pad.length;el.focus();el.setSelectionRange(pos,pos);screenState().query[state.strategy]=el.value;persist();}

document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b)return;const name=b.dataset.action;
 switch(name){
 case 'chat-toggle':{state.chatOpen=!state.chatOpen;const y=scrollY;render();window.scrollTo(0,y);if(state.chatOpen)$('#chat-msg')?.focus?.({preventScroll:true});else $('.chat-fab')?.focus?.({preventScroll:true});break;}
 case 'chat-suggest':sendChat(b.dataset.text);break;
 case 'set-exchange':{const ex=b.dataset.exchange==='BSE'?'BSE':'NSE';if(state.exchange!==ex){state.exchange=ex;persist();const y=scrollY;render();window.scrollTo(0,y);toast('Exchange set to '+ex+'.');}break;}
 case 'screen-insert':insertScreenToken(b.dataset.token);break;
 case 'screen-ratio-tab':{(state.screens=state.screens||{}).ratioTab=b.dataset.tab;saveScreenQuery();persist();const y=scrollY;render();window.scrollTo(0,y);break;}
 case 'screen-run':saveScreenQuery();{const y=scrollY;render();window.scrollTo(0,y);}toast(runScreen(getScreenQuery()).length+' companies matched.');break;
 case 'screen-clear':{const el=$('#screen-query');if(el){el.value='';screenState().query[state.strategy]='';persist();render();}break;}
 case 'screen-save':{const q=getScreenQuery();saveScreenQuery();showDialog('Save screen',`<form data-form="save-screen"><div class="form-group"><label class="label" for="screen-name">Screen name</label><input class="field" id="screen-name" name="name" required placeholder="My value screen"></div><input type="hidden" name="query" value="${esc(q)}"><button class="btn primary" type="submit">Save screen</button></form>`);break;}
 case 'screen-view':{(state.screens=state.screens||{}).view=b.dataset.view==='directory'?'directory':b.dataset.view==='saved'?'saved':'builder';saveScreenQuery();persist();if(currentRoute!=='analysis/screens'){go('analysis/screens');}render();break;}
 case 'screen-open-saved':{const s=screenState().saved[Number(b.dataset.index)];if(s){screenState().query[state.strategy]=s.query;(state.screens=state.screens||{}).view='builder';persist();go('analysis/screens');render();}break;}
 case 'screen-delete-saved':{screenState().saved.splice(Number(b.dataset.index),1);persist();render();toast('Screen deleted.');break;}
 case 'screen-load-template':{const tpl={'Golden crossover':'Return over 3months > 5 AND Return on equity > 12','Golden Crossover':'Return over 3months > 5 AND Return on equity > 12','Volume surge 2x':'Return over 3months > 8','RSI oversold reversal':'RSI < 40','VCP coiling':'Return over 3months > 0 AND Return on equity > 15','52-week high today':'Return over 6months > 20','RSI — Oversold Stocks':'RSI < 30','Highest Dividend Yield':'Dividend yield > 1','Magic Formula':'Return on capital employed > 20 AND Price to Earning < 20','Piotroski Scan':'Return on equity > 15 AND Debt to equity < 1','Capacity expansion':'Sales growth > 15','Companies creating new high':'Return over 6months > 15'}[b.dataset.name]||('Return on equity > 15 AND Market Capitalization > 500');screenState().query[state.strategy]=tpl;(state.screens=state.screens||{}).view='builder';persist();go('analysis/screens');render();toast('Loaded: '+b.dataset.name);break;}
 case 'screen-new-ratio':showDialog('Create a new ratio',`<p>Combine existing fields with operators to define a custom ratio. For example: <code>Profit after tax / Sales * 100</code> for net margin.</p><form data-form="new-ratio"><div class="form-group"><label class="label" for="ratio-name">Ratio name</label><input class="field" id="ratio-name" name="name" required></div><div class="form-group"><label class="label" for="ratio-expr">Formula</label><input class="field" id="ratio-expr" name="expr" placeholder="Profit after tax / Sales * 100" required></div><button class="btn primary" type="submit">Create ratio</button></form>`);break;
 case 'auto-execute':runAutoExecute(b);break;
 case 'one-click-execute':{const f=b.closest('form');if(f)runOneClick(f);break;}
 case 'auto-exec-preview':autoExecPreview();break;
 case 'pricing-select':showDialog(b.dataset.plan==='Institutional'?'Contact sales':'Choose '+b.dataset.plan,`<p>${b.dataset.plan==='Institutional'?'Tell us about your team and we will prepare a quote.':'Full access is free through 31 December 2026 — no payment details required. This is a layout-only selection.'}</p>`,action('Close','close-dialog','btn primary'));break;
 case 'analysis-preview-toggle':state.analysisPreview=!(state.analysisPreview!==false);persist();break;
 case 'analysis-create-alert':toast('Alert connected to this scan.');break;
 case 'analysis-indicators':showDialog('Indicators',`<p>Choose from overlays and oscillators.</p><div class="calc-grid">${['Moving Average','Bollinger Bands','RSI','MACD','Stochastic','VWAP','ATR','Supertrend'].map(n=>`<button type="button" class="calc-chip" data-action="close-dialog">${n}</button>`).join('')}</div>`);break;
 case 'nav-tools-backtest':go('tools/backtest');render();break;
 case 'calc-open':showDialog(b.dataset.calc,`<p>${esc(b.dataset.calc)} — enter your inputs.</p><form data-form="generic-calc"><div class="form-group"><label class="label" for="calc-a">Amount</label><input class="field" id="calc-a" type="number" value="100000"></div><div class="form-group"><label class="label" for="calc-b">Rate / years</label><input class="field" id="calc-b" type="number" value="12"></div><button class="btn primary" type="submit">Calculate</button></form><p class="field-help">Calculator inputs are illustrative.</p>`);break;
 case 'show-shortcuts':case 'shortcuts-overlay':showDialog('Keyboard shortcuts',shortcutsTable());break;
 }
});

