document.addEventListener('input',event=>{const el=event.target;
 if(el.id==='ratio-search-input'){const q=el.value.toLowerCase();$$('#ratio-list .ratio-item').forEach(item=>{item.hidden=!item.textContent.toLowerCase().includes(q);});}
 if(el.closest('#tool-sizing')){const f=el.closest('form'),cap=+f.capital.value||0,risk=+f.risk.value||0,entry=+f.entry.value||0,stop=+f.stop.value||0,per=Math.abs(entry-stop),riskAmt=cap*risk/100,shares=per?Math.floor(riskAmt/per):0,box=$('#sizing-result');if(box)box.innerHTML=analysisMetric('Risk amount',money(riskAmt),risk+'% of capital','shield')+analysisMetric('Shares',String(shares),'Whole shares','portfolio')+analysisMetric('Position value',money(shares*entry),'At entry','wallet');}
 if(el.closest('#calc-sip')){const f=el.closest('form'),amt=+f.amount.value||0,rate=+f.rate.value||0,yrs=+f.years.value||0,n=yrs*12,i=rate/100/12,fv=i?amt*((Math.pow(1+i,n)-1)/i)*(1+i):amt*n,box=$('#sip-result');if(box)box.innerHTML=analysisMetric('Invested',money(amt*n),'Total','wallet')+analysisMetric('Future value',money(fv),'At maturity','chart');}
});

