 if(f.id==='screen-search'||f.id==='analysis-scan-search'||f.id==='analysis-symbol'||f.id==='analysis-symbol'){event.preventDefault();toast('Filtered.');return;}
 if(f.dataset.form==='save-screen'){event.preventDefault();const d=new FormData(f),nm=String(d.get('name')||'').trim();if(nm){screenState().saved.push({name:nm,query:screenState().query[state.strategy]});(state.screens=state.screens||{}).view='saved';persist();$('#dialog').close();go('analysis/screens');render();toast('Screen saved.');}return;}
 if(f.dataset.form==='new-ratio'){event.preventDefault();$('#dialog').close();toast('Custom ratio created (local).');return;}
 if(f.dataset.form==='auto-exec'){event.preventDefault();runAutoExecuteForm(f);return;}
