function collectAutoExec(f){const key=state.strategy;(state.autoExec=state.autoExec||{});const ex=state.autoExec[key]=state.autoExec[key]||{};ex.budget=+f.budget.value||state.budgets[key];ex.stop=+f.stop.value||0;ex.target=+f.target.value||0;ex.risk=+f.risk.value||1;ex.orderType=f.orderType.value;persist();return ex;}
function runAutoExecuteForm(f){const ex=collectAutoExec(f);finishAutoExecute(ex,f.confirm&&f.confirm.checked);}
function runAutoExecute(btn){if(btn.classList.contains('disabled'))return;const f=btn.closest('form');const ex=f?collectAutoExec(f):(state.autoExec?.[state.strategy]||{});finishAutoExecute(ex,!f||(f.confirm&&f.confirm.checked));}
function finishAutoExecute(ex,confirmed){const key=state.strategy;if(state.paused[key]){toast('Automation is paused — resume it to execute.');return;}if(!selected().length){toast('Select stocks for this strategy first.');return;}if(!confirmed){toast('Tick the authorisation box to execute.');return;}
 const ids=selected(),now=new Date().toLocaleString('en-IN',{hour12:false});
 ex.lastRun={time:now+' IST',count:ids.length,budget:ex.budget,stop:ex.stop,target:ex.target};persist();
 if(typeof recordAudit==='function')recordAudit('Execution','Automated execution run',strategy().name+' · '+ids.length+' entries · '+(state.exchange||'NSE'));
 showDialog('Execution queued',`<p>The model has queued ${ids.length} condition-based ${strategy().name} entr${ids.length===1?'y':'ies'} on your ${esc(state.exchange||'NSE')} account.</p><div class="auto-exec-summary">${lines([['Budget',money(ex.budget)],['Stop-loss',ex.stop+'%'],['Target',ex.target+'%'],['Max risk / trade',ex.risk+'%'],['Order type',ex.orderType||'Limit']])}</div><p class="field-help">This is a presentation flow. No real order is placed — production execution requires authenticated broker APIs, live data, and risk checks on the server.</p>`,action('Done','close-dialog','btn primary'));
 const y=scrollY;render();window.scrollTo(0,y);}
function autoExecPreview(){const ids=selected();if(!ids.length){toast('No stocks selected.');return;}const ex=state.autoExec?.[state.strategy]||{};const budget=ex.budget||state.budgets[state.strategy];const per=budget*0.9/ids.length;showDialog('Execution dry-run — '+strategy().name,table(['Company','Qty','Entry','Stop','Target'],ids.map(id=>{const c=stock(id),qty=Math.floor(per/c.price),stopPx=c.price*(1-(ex.stop||5)/100),tgtPx=c.price*(1+(ex.target||10)/100);return `<tr><td>${esc(c.name)}</td><td>${qty}</td><td>${fixed(c.price)}</td><td>${fixed(stopPx)}</td><td>${fixed(tgtPx)}</td></tr>`;})),action('Close','close-dialog')+action(icon('play')+'Execute now','auto-execute','btn primary'));}

/* Keyboard shortcuts are handled in settings-pro.js. */

